ORIGINAL = {
    "platform.ai_provider_session(jsonb,boolean)": "CREATE OR REPLACE FUNCTION platform.ai_provider_session(p jsonb,p_enable boolean) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE s platform.ai_provider_sessions%ROWTYPE; old platform.ai_provider_sessions%ROWTYPE;\nBEGIN\n  IF session_user<>'asm_migrator' OR current_database()<>'asm_test' OR p_enable IS NULL THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  IF p_enable IS FALSE THEN\n    IF NOT platform.material_object(p,ARRAY['session_id']) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n    UPDATE platform.ai_provider_sessions SET active=false WHERE id=(p->>'session_id')::uuid;\n    IF NOT FOUND THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n    RETURN jsonb_build_object('code','DISABLED');\n  END IF;\n  IF NOT platform.material_object(p,ARRAY['session_id','workspace_id','connection_id','conversation_id','client_id','chat_id','bot_identity','data_profile','starts_at','expires_at','max_calls','max_rub','review_sha256','review_checked_at','config'])\n    OR platform.ai_provider_config_valid(p->'config') IS NOT TRUE\n    OR (p->>'data_profile',p->'config'->>'prompt_revision') NOT IN\n      (('SYNTHETIC_TEXT_V1','conversation_v2'),('SYNTHETIC_PUBLISHED_KNOWLEDGE_V1','conversation_v3'))\n    OR p->'config'->>'revision' IS DISTINCT FROM 'polza-'||(p->>'session_id')||'-'||(p->>'review_sha256')\n    OR (platform.knowledge_search_schema_profile()->>'valid')::boolean IS NOT TRUE THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  s:=jsonb_populate_record(NULL::platform.ai_provider_sessions,(p-'session_id')||jsonb_build_object('id',p->>'session_id','active',true,'created_at',clock_timestamp()));\n  IF s.starts_at>clock_timestamp() OR s.expires_at<=clock_timestamp() OR s.review_checked_at>clock_timestamp()\n    OR s.review_checked_at<clock_timestamp()-interval '24 hours'\n    OR (s.config->'limits'->>'call_cost_reservation')::numeric*s.max_calls>s.max_rub\n    OR NOT EXISTS(SELECT 1 FROM app.conversations c JOIN app.channel_connections cc ON (cc.workspace_id,cc.id)=(c.workspace_id,c.connection_id)\n      WHERE (c.workspace_id,c.id,c.connection_id,c.client_id,c.provider_chat_id)=(s.workspace_id,s.conversation_id,s.connection_id,s.client_id,s.chat_id)\n      AND cc.provider='TELEGRAM' AND cc.bot_identity=s.bot_identity AND cc.status='ACTIVE') THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  SELECT * INTO old FROM platform.ai_provider_sessions WHERE id=s.id FOR UPDATE;\n  IF FOUND THEN\n    IF (to_jsonb(old)-'created_at') IS DISTINCT FROM (to_jsonb(s)-'created_at') THEN\n      RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n    RETURN jsonb_build_object('code','ALREADY_ENABLED');\n  END IF;\n  INSERT INTO platform.ai_provider_sessions SELECT s.*;\n  RETURN jsonb_build_object('code','ENABLED');\nEND $$",
    "platform.configuration_command(uuid,text,text,jsonb)": "CREATE OR REPLACE FUNCTION platform.configuration_command(p_business uuid,p_operation text,p_key text,p jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE ws uuid; actor uuid; corr uuid; fingerprint bytea; prior platform.business_configuration_receipts%ROWTYPE;\n        s platform.business_configuration_state%ROWTYPE; r platform.business_configuration_releases%ROWTYPE;\n        current_body jsonb; v jsonb; result jsonb; receipt uuid; moment timestamptz; expected bigint;\n      BEGIN\n        PERFORM platform.turn_require_isolation(); ws:=app.current_workspace_id(); actor:=nullif(current_setting('asm.actor_id',true),'')::uuid;\n        IF ws IS NULL OR platform.messaging_lock_owner(ws,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2701'; END IF;\n        PERFORM 1 FROM app.businesses WHERE workspace_id=ws AND id=p_business AND status='ACTIVE' FOR SHARE;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2701'; END IF;\n        IF p_operation IS NULL OR p_operation NOT IN ('EDIT','PUBLISH','ROLLBACK') OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$'\n          OR platform.material_object(p,CASE p_operation WHEN 'EDIT' THEN ARRAY['expected_draft_version','bundle']\n            WHEN 'PUBLISH' THEN ARRAY['expected_draft_version','expected_activation_version'] ELSE ARRAY['expected_activation_version','release_id'] END) IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2701'; END IF;\n        IF p_operation IN ('EDIT','PUBLISH') AND platform.human_context_decimal(p->'expected_draft_version',false) IS NOT TRUE\n          OR p_operation IN ('PUBLISH','ROLLBACK') AND platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE\n          OR p_operation='ROLLBACK' AND platform.human_context_uuid(p->'release_id') IS NOT TRUE\n          OR p_operation='EDIT' AND platform.configuration_bundle_shape(p->'bundle') IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2701'; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(ws::text||':'||p_business::text||'|CONFIGURATION_V1',2018));\n        IF platform.messaging_lock_owner(ws,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2701'; END IF;\n        fingerprint:=sha256(convert_to(E'asm:m5:configuration:v1\\n'||jsonb_build_array(ws,actor,p_business,p_operation,p)::text,'UTF8'));\n        SELECT * INTO prior FROM platform.business_configuration_receipts WHERE workspace_id=ws AND business_id=p_business AND idempotency_key=p_key;\n        IF FOUND THEN\n          IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2701'; END IF;\n          RETURN jsonb_build_object('outcome','REPLAY','result',prior.result); END IF;\n        SELECT * INTO s FROM platform.business_configuration_state WHERE workspace_id=ws AND business_id=p_business FOR UPDATE;\n        moment:=clock_timestamp(); receipt:=uuidv7(); corr:=nullif(current_setting('asm.correlation_id',true),'')::uuid;\n        IF p_operation='EDIT' THEN\n          expected:=(p->>'expected_draft_version')::bigint;\n          IF expected<>coalesce(s.draft_version,0) THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2701'; END IF;\n          IF expected=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2701'; END IF;\n          IF s.workspace_id IS NULL THEN\n            INSERT INTO platform.business_configuration_state(workspace_id,business_id,draft_version,draft_body,updated_at)\n              VALUES(ws,p_business,1,p->'bundle',moment) RETURNING * INTO s;\n          ELSE UPDATE platform.business_configuration_state SET draft_version=draft_version+1,draft_body=p->'bundle',updated_at=moment\n            WHERE workspace_id=ws AND business_id=p_business RETURNING * INTO s; END IF;\n        ELSE\n          IF s.workspace_id IS NULL OR s.activation_version<>(p->>'expected_activation_version')::bigint\n            OR p_operation='PUBLISH' AND s.draft_version<>(p->>'expected_draft_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2701'; END IF;\n          IF s.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2701'; END IF;\n          IF p_operation='PUBLISH' THEN\n            IF EXISTS(SELECT 1 FROM platform.knowledge_release_builds WHERE workspace_id=ws AND business_id=p_business AND release_id=s.active_release_id) THEN RAISE EXCEPTION 'KNOWLEDGE_BUILD_REQUIRED' USING ERRCODE='P2701'; END IF;\n            IF platform.configuration_validate(s.draft_body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2701'; END IF;\n            INSERT INTO platform.business_configuration_releases(workspace_id,business_id,source_draft_version,body,published_by,published_at)\n              VALUES(ws,p_business,s.draft_version,s.draft_body,actor,moment) RETURNING * INTO r;\n          ELSE\n            SELECT * INTO r FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=p_business AND id=(p->>'release_id')::uuid;\n            IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2701'; END IF;\n            IF EXISTS(SELECT 1 FROM platform.knowledge_release_builds WHERE workspace_id=ws AND business_id=p_business AND release_id=r.id) AND platform.knowledge_release_eligible(ws,p_business,r.id) IS NOT TRUE THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            IF platform.configuration_validate(r.body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2701'; END IF;\n            SELECT body INTO current_body FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=p_business AND id=s.active_release_id;\n            FOR v IN SELECT value FROM jsonb_array_elements(r.body->'faqs') LOOP\n              IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_body->'faqs') c WHERE c=v) THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            END LOOP;\n            FOR v IN SELECT value FROM jsonb_array_elements(r.body->'services') LOOP\n              IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_body->'services') c WHERE c->'id'=v->'id'\n                AND jsonb_build_array(c->'name',c->'description',c->'intake_fields',c->'price'->'formula_note',c->'duration'->'rule_note')\n                  =jsonb_build_array(v->'name',v->'description',v->'intake_fields',v->'price'->'formula_note',v->'duration'->'rule_note')) THEN\n                RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            END LOOP;\n          END IF;\n          UPDATE platform.business_configuration_state SET active_release_id=r.id,activation_version=activation_version+1,updated_at=moment\n            WHERE workspace_id=ws AND business_id=p_business RETURNING * INTO s;\n        END IF;\n        result:=jsonb_build_object('workspace_id',ws,'business_id',p_business,'receipt_id',receipt,'operation',p_operation,\n          'draft_version',s.draft_version::text,'release_id',s.active_release_id,'activation_version',s.activation_version::text,\n          'recorded_at',to_char(moment AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'));\n        INSERT INTO platform.business_configuration_receipts(workspace_id,business_id,id,operation,idempotency_key,actor_user_account_id,correlation_id,request_fingerprint,result,recorded_at)\n          VALUES(ws,p_business,receipt,p_operation,p_key,actor,corr,fingerprint,result,moment);\n        RETURN jsonb_build_object('outcome','ACCEPTED','result',result);\n      END $$",
    "platform.knowledge_owner_command(uuid,text,text,jsonb)": "CREATE FUNCTION platform.knowledge_owner_command(business uuid,operation text,p_key text,p jsonb) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE ws uuid:=platform.knowledge_owner_lock(business); actor uuid:=nullif(current_setting('asm.actor_id',true),'')::uuid;\n  fields text[]; fingerprint bytea; prior platform.business_configuration_receipts%ROWTYPE;\n  s platform.knowledge_sources%ROWTYPE; r platform.knowledge_revisions%ROWTYPE; b platform.knowledge_builds%ROWTYPE;\n  config platform.business_configuration_state%ROWTYPE; release platform.business_configuration_releases%ROWTYPE;\n  canonical text; plan jsonb; chunk jsonb; source uuid; next_no bigint; result jsonb; receipt uuid:=uuidv7(); moment timestamptz:=clock_timestamp(); affected boolean;\nBEGIN\n  fields:=CASE operation\n    WHEN 'KNOWLEDGE_SAVE' THEN ARRAY['schema_version','source_id','expected_source_version','title','format','text','source_label','author_label','service_id','category','claim_key','effective_from','effective_until']\n    WHEN 'KNOWLEDGE_CONFIRM' THEN ARRAY['schema_version','source_id','expected_source_version','revision_id','canonical_sha256']\n    WHEN 'KNOWLEDGE_REVOKE' THEN ARRAY['schema_version','source_id','expected_source_version','expected_activation_version']\n    WHEN 'KNOWLEDGE_DELETE' THEN ARRAY['schema_version','source_id','expected_source_version','expected_activation_version']\n    WHEN 'KNOWLEDGE_BUILD_CREATE' THEN ARRAY['schema_version','expected_sources_hash','revision_ids']\n    WHEN 'KNOWLEDGE_PUBLISH' THEN ARRAY['schema_version','expected_draft_version','expected_activation_version','build_id','expected_build_version']\n    WHEN 'KNOWLEDGE_ROLLBACK' THEN ARRAY['schema_version','expected_activation_version','release_id'] END;\n  IF fields IS NULL OR platform.material_object(p,fields) IS NOT TRUE OR p->'schema_version' IS DISTINCT FROM '1'::jsonb OR p->>'schema_version'<>'1'\n    OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$' OR octet_length(convert_to(p::text,'UTF8'))>8192 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  fingerprint:=sha256(convert_to(E'asm:m5:knowledge:v1\\n'||jsonb_build_array(ws,actor,business,operation,p)::text,'UTF8'));\n  SELECT * INTO prior FROM platform.business_configuration_receipts WHERE workspace_id=ws AND business_id=business AND idempotency_key=p_key;\n  IF FOUND THEN\n    IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2801'; END IF;\n    RETURN jsonb_build_object('schema_version',1,'outcome','REPLAY','result',prior.result); END IF;\n  SELECT * INTO config FROM platform.business_configuration_state WHERE workspace_id=ws AND business_id=business FOR UPDATE;\n  IF operation IN ('KNOWLEDGE_SAVE','KNOWLEDGE_CONFIRM','KNOWLEDGE_REVOKE','KNOWLEDGE_DELETE') THEN\n    IF platform.human_context_decimal(p->'expected_source_version',false) IS NOT TRUE OR NOT (p->'source_id'='null'::jsonb OR platform.human_context_uuid(p->'source_id')) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    source:=(p->>'source_id')::uuid;\n    IF source IS NOT NULL THEN\n      SELECT * INTO s FROM platform.knowledge_sources WHERE workspace_id=ws AND business_id=business AND id=source FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2801'; END IF;\n      IF s.state='DELETED' THEN RAISE EXCEPTION 'SOURCE_DELETED' USING ERRCODE='P2801'; END IF;\n    ELSIF operation<>'KNOWLEDGE_SAVE' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF coalesce(s.version,0)<>(p->>'expected_source_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF s.version=9223372036854775807 OR s.revocation_epoch=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n  END IF;\n  IF operation='KNOWLEDGE_SAVE' THEN\n    canonical:=platform.knowledge_normalize(p->>'text');\n    IF jsonb_typeof(p->'text') IS DISTINCT FROM 'string' OR octet_length(convert_to(canonical,'UTF8')) NOT BETWEEN 1 AND 2048 OR NOT platform.human_context_text_valid(canonical)\n      OR NOT platform.configuration_text_valid(p->'title',120,true) OR p->>'format' NOT IN ('TEXT','MARKDOWN') OR NOT platform.configuration_text_valid(p->'source_label',120,true)\n      OR NOT (p->'author_label'='null'::jsonb OR platform.configuration_text_valid(p->'author_label',80,false)) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    FOR canonical IN SELECT key FROM jsonb_each(p) WHERE key IN ('service_id','category','claim_key') LOOP\n      IF NOT (p->canonical='null'::jsonb OR jsonb_typeof(p->canonical)='string' AND p->>canonical ~ '^[a-z][a-z0-9_-]{0,39}$') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    END LOOP;\n    FOR canonical IN SELECT key FROM jsonb_each(p) WHERE key IN ('effective_from','effective_until') LOOP\n      IF p->canonical<>'null'::jsonb AND (jsonb_typeof(p->canonical)<>'string' OR p->>canonical !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'\n        OR NOT isfinite((p->>canonical)::timestamptz) OR to_char((p->>canonical)::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"')<>p->>canonical) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    END LOOP;\n    IF p->>'effective_from' IS NOT NULL AND p->>'effective_until' IS NOT NULL AND (p->>'effective_until')::timestamptz<=(p->>'effective_from')::timestamptz THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    canonical:=platform.knowledge_normalize(p->>'text');\n    IF s.id IS NULL THEN\n      IF (SELECT count(*) FROM platform.knowledge_sources WHERE workspace_id=ws AND business_id=business AND state<>'DELETED')>=8 THEN RAISE EXCEPTION 'SOURCE_LIMIT' USING ERRCODE='P2801'; END IF;\n      INSERT INTO platform.knowledge_sources(workspace_id,business_id,state) VALUES(ws,business,'DRAFT') RETURNING * INTO s;\n      next_no:=1;\n    ELSE\n      SELECT revision_no+1 INTO next_no FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND id=s.head_revision_id;\n      IF next_no IS NULL THEN RAISE EXCEPTION 'SOURCE_DELETED' USING ERRCODE='P2801'; END IF;\n    END IF;\n    INSERT INTO platform.knowledge_revisions(workspace_id,business_id,source_id,revision_no,title,format,canonical_text,canonical_sha256,source_label,author_label,service_id,category,claim_key,effective_from,effective_until,created_by)\n      VALUES(ws,business,s.id,next_no,p->>'title',p->>'format',canonical,encode(sha256(convert_to(canonical,'UTF8')),'hex'),p->>'source_label',p->>'author_label',p->>'service_id',p->>'category',p->>'claim_key',(p->>'effective_from')::timestamptz,(p->>'effective_until')::timestamptz,actor) RETURNING * INTO r;\n    plan:=platform.knowledge_plan(canonical);\n    FOR chunk IN SELECT value FROM jsonb_array_elements(plan->'chunks') LOOP\n      INSERT INTO platform.knowledge_chunks(workspace_id,business_id,revision_id,ordinal,text,sha256) VALUES(ws,business,r.id,(chunk->>'ordinal')::integer,chunk->>'text',chunk->>'sha256');\n    END LOOP;\n    UPDATE platform.knowledge_sources SET head_revision_id=r.id,state='DRAFT',version=CASE WHEN source IS NULL THEN version ELSE version+1 END WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n  ELSIF operation='KNOWLEDGE_CONFIRM' THEN\n    IF platform.human_context_uuid(p->'revision_id') IS NOT TRUE OR p->>'canonical_sha256' !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    SELECT * INTO r FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND id=s.head_revision_id;\n    IF r.id::text IS DISTINCT FROM p->>'revision_id' OR r.canonical_sha256 IS DISTINCT FROM p->>'canonical_sha256' THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF platform.knowledge_plan(r.canonical_text)->'issues'<>'[]'::jsonb THEN RAISE EXCEPTION 'CHUNK_LIMIT' USING ERRCODE='P2801'; END IF;\n    IF r.confirmed THEN\n      IF r.confirmed_epoch<>s.revocation_epoch THEN RAISE EXCEPTION 'SOURCE_REVOKED' USING ERRCODE='P2801'; END IF;\n    ELSE UPDATE platform.knowledge_revisions SET confirmed=true,confirmed_by=actor,confirmed_at=moment,confirmed_epoch=s.revocation_epoch WHERE workspace_id=ws AND business_id=business AND id=r.id RETURNING * INTO r;\n      UPDATE platform.knowledge_sources SET confirmed_revision_id=r.id,state='CONFIRMED',version=version+1 WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n    END IF;\n  ELSIF operation IN ('KNOWLEDGE_REVOKE','KNOWLEDGE_DELETE') THEN\n    IF platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF coalesce(config.activation_version,0)<>(p->>'expected_activation_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    affected:=EXISTS(SELECT 1 FROM platform.knowledge_release_builds l JOIN platform.knowledge_builds kb ON (kb.workspace_id,kb.business_id,kb.id)=(l.workspace_id,l.business_id,l.build_id),jsonb_array_elements(kb.manifest) m\n      WHERE l.workspace_id=ws AND l.business_id=business AND l.release_id=config.active_release_id AND m->>'source_id'=s.id::text);\n    IF affected AND config.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n    DELETE FROM platform.knowledge_build_chunks p USING platform.knowledge_chunks c,platform.knowledge_revisions kr WHERE (p.workspace_id,p.business_id,p.chunk_id)=(c.workspace_id,c.business_id,c.id)\n      AND (kr.workspace_id,kr.business_id,kr.id)=(c.workspace_id,c.business_id,c.revision_id) AND kr.workspace_id=ws AND kr.business_id=business AND kr.source_id=s.id;\n    UPDATE platform.knowledge_sources SET state=CASE WHEN operation='KNOWLEDGE_DELETE' THEN 'DELETED' ELSE 'REVOKED' END,version=version+1,revocation_epoch=revocation_epoch+1,revoked_at=moment,\n      deleted_at=CASE WHEN operation='KNOWLEDGE_DELETE' THEN moment END,head_revision_id=CASE WHEN operation='KNOWLEDGE_DELETE' THEN NULL ELSE head_revision_id END,\n      confirmed_revision_id=CASE WHEN operation='KNOWLEDGE_DELETE' THEN NULL ELSE confirmed_revision_id END WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n    IF operation='KNOWLEDGE_DELETE' THEN\n      DELETE FROM platform.knowledge_chunks c USING platform.knowledge_revisions kr WHERE (kr.workspace_id,kr.business_id,kr.id)=(c.workspace_id,c.business_id,c.revision_id) AND kr.workspace_id=ws AND kr.business_id=business AND kr.source_id=s.id;\n      DELETE FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND source_id=s.id;\n    END IF;\n    IF affected THEN UPDATE platform.business_configuration_state SET activation_version=activation_version+1,updated_at=moment WHERE workspace_id=ws AND business_id=business RETURNING * INTO config; END IF;\n  ELSIF operation='KNOWLEDGE_BUILD_CREATE' THEN\n    b:=platform.knowledge_build_create(ws,business,actor,p);\n  ELSIF operation IN ('KNOWLEDGE_PUBLISH','KNOWLEDGE_ROLLBACK') THEN\n    IF platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE OR config.workspace_id IS NULL OR config.activation_version<>(p->>'expected_activation_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF config.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n    IF operation='KNOWLEDGE_PUBLISH' THEN\n      IF platform.human_context_uuid(p->'build_id') IS NOT TRUE OR platform.human_context_decimal(p->'expected_build_version',true) IS NOT TRUE\n        OR platform.human_context_decimal(p->'expected_draft_version',true) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n      SELECT * INTO b FROM platform.knowledge_builds WHERE workspace_id=ws AND business_id=business AND id=(p->>'build_id')::uuid FOR UPDATE;\n      IF b.id IS NULL OR b.version<>(p->>'expected_build_version')::bigint OR config.draft_version<>(p->>'expected_draft_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n      IF platform.knowledge_build_valid(ws,business,b.id,true) IS NOT TRUE THEN RAISE EXCEPTION 'BUILD_NOT_READY' USING ERRCODE='P2801'; END IF;\n      IF platform.configuration_validate(config.draft_body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2801'; END IF;\n      IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.manifest) m JOIN platform.knowledge_revisions kr ON (kr.workspace_id,kr.business_id,kr.id)=(ws,business,(m->>'revision_id')::uuid)\n        WHERE kr.service_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(config.draft_body->'services') service WHERE service->>'id'=kr.service_id AND service->'active'='true'::jsonb)) THEN RAISE EXCEPTION 'INVALID_REFERENCE' USING ERRCODE='P2801'; END IF;\n      INSERT INTO platform.business_configuration_releases(workspace_id,business_id,source_draft_version,body,published_by,published_at) VALUES(ws,business,config.draft_version,config.draft_body,actor,moment) RETURNING * INTO release;\n      INSERT INTO platform.knowledge_release_builds(workspace_id,business_id,release_id,build_id) VALUES(ws,business,release.id,b.id);\n    ELSE\n      IF platform.human_context_uuid(p->'release_id') IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n      SELECT * INTO release FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=business AND id=(p->>'release_id')::uuid;\n      IF release.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2801'; END IF;\n      IF platform.knowledge_release_eligible(ws,business,release.id) IS NOT TRUE THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2801'; END IF;\n      SELECT kb.* INTO b FROM platform.knowledge_release_builds l JOIN platform.knowledge_builds kb ON (kb.workspace_id,kb.business_id,kb.id)=(l.workspace_id,l.business_id,l.build_id) WHERE l.workspace_id=ws AND l.business_id=business AND l.release_id=release.id;\n    END IF;\n    UPDATE platform.business_configuration_state SET active_release_id=release.id,activation_version=activation_version+1,updated_at=moment WHERE workspace_id=ws AND business_id=business RETURNING * INTO config;\n  END IF;\n  result:=jsonb_build_object('workspace_id',ws,'business_id',business,'receipt_id',receipt,'operation',operation,\n    'source_id',s.id,'source_version',s.version::text,'revision_id',r.id,'build_id',b.id,'build_version',b.version::text,\n    'release_id',config.active_release_id,'activation_version',coalesce(config.activation_version,0)::text,\n    'recorded_at',to_char(moment AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),'request_hash',encode(fingerprint,'hex'));\n  INSERT INTO platform.business_configuration_receipts(workspace_id,business_id,id,operation,idempotency_key,actor_user_account_id,correlation_id,request_fingerprint,result,recorded_at)\n    VALUES(ws,business,receipt,operation,p_key,actor,nullif(current_setting('asm.correlation_id',true),'')::uuid,fingerprint,result,moment);\n  RETURN jsonb_build_object('schema_version',1,'outcome','ACCEPTED','result',result);\nEXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801';\nEND $$",
    "platform.knowledge_embedding_complete(uuid,uuid,jsonb)": "CREATE FUNCTION platform.knowledge_embedding_complete(p_call uuid,p_ticket uuid,p jsonb) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE ec platform.knowledge_embedding_calls%ROWTYPE; record jsonb; completion_state text; validation text; vectors_hash text; next_state text; valid_usage boolean; detail_name text; detail jsonb; detail_item record; raw_cost jsonb; reported_cost numeric;\nBEGIN\n  IF current_database() NOT IN ('asm_local','asm_test') OR p_ticket IS NULL THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2801'; END IF;\n  SELECT * INTO ec FROM platform.knowledge_embedding_calls WHERE id=p_call;\n  IF ec.id IS NULL OR ec.ticket_hash IS DISTINCT FROM sha256(convert_to(p_ticket::text,'UTF8')) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2801'; END IF;\n  IF ec.kind='INDEX_BATCH' THEN\n    PERFORM pg_advisory_xact_lock(hashtextextended(ec.workspace_id::text||':'||ec.business_id::text||'|CONFIGURATION_V1',2018));\n    PERFORM 1 FROM platform.knowledge_builds WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.build_id FOR UPDATE;\n  END IF;\n  SELECT * INTO STRICT ec FROM platform.knowledge_embedding_calls WHERE id=p_call FOR UPDATE;\n  IF platform.material_object(p,ARRAY['kind','vectors','usage','cost','identity','request_id','error_code']) IS NOT TRUE OR octet_length(p::text)>262144\n    OR p->>'kind' NOT IN ('SUCCESS','ERROR','UNKNOWN') OR jsonb_typeof(p->'usage') IS DISTINCT FROM 'object' OR octet_length((p->'usage')::text)>2048\n    OR platform.material_object(p->'cost',ARRAY['status','amount','currency']) IS NOT TRUE OR p->'cost'->>'status' NOT IN ('CONFIRMED','UNKNOWN') OR p->'cost'->>'currency'<>'RUB'\n    OR platform.material_object(p->'identity',ARRAY['status','source','provider','model']) IS NOT TRUE OR p->'identity'->>'status' NOT IN ('CONFIRMED','UNVERIFIED')\n    OR p->'identity'->>'source' NOT IN ('BODY','HISTORY','NONE') OR NOT (p->'identity'->'provider'='null'::jsonb OR p->'identity'->>'provider'='OpenAI')\n    OR NOT (p->'identity'->'model'='null'::jsonb OR jsonb_typeof(p->'identity'->'model')='string' AND char_length(p->'identity'->>'model')<=128)\n    OR NOT (p->'request_id'='null'::jsonb OR jsonb_typeof(p->'request_id')='string' AND p->>'request_id' ~ '^[A-Za-z0-9._:-]{1,128}$')\n    OR NOT (p->'error_code'='null'::jsonb OR p->>'error_code' IN ('TRANSPORT','TIMEOUT','INVALID_RESPONSE','PROFILE_MISMATCH','IDENTITY_UNVERIFIED','USAGE_INVALID','COST_UNKNOWN','COST_LIMIT','DISABLED','CANCELLED','SOURCE_STALE')) THEN\n    RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  IF p->'cost'->>'status'='UNKNOWN' THEN\n    IF p->'cost'->'amount'<>'null'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  ELSE\n    IF jsonb_typeof(p->'cost'->'amount') IS DISTINCT FROM 'string' OR p->'cost'->>'amount' !~ '^(0|[1-9][0-9]{0,6})([.][0-9]{1,9})?$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF (p->'cost'->>'amount')::numeric>1000000 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  END IF;\n  completion_state:=CASE WHEN NOT (p->'usage' ? 'completion_tokens') THEN 'NOT_APPLICABLE'\n    WHEN jsonb_typeof(p->'usage'->'completion_tokens')='number' AND p->'usage'->>'completion_tokens'='0' THEN 'ZERO' ELSE 'INVALID' END;\n  valid_usage:=coalesce(NOT EXISTS(SELECT 1 FROM jsonb_object_keys(p->'usage') AS u(name) WHERE name NOT IN\n      ('prompt_tokens','total_tokens','completion_tokens','cost','cost_rub','prompt_tokens_details','completion_tokens_details','server_tool_use'))\n    AND jsonb_typeof(p->'usage'->'prompt_tokens')='number' AND p->'usage'->>'prompt_tokens' ~ '^[1-9][0-9]{0,6}$'\n    AND jsonb_typeof(p->'usage'->'total_tokens')='number' AND p->'usage'->>'total_tokens' ~ '^[1-9][0-9]{0,6}$'\n    AND p->'usage'->'prompt_tokens'=p->'usage'->'total_tokens'\n    AND CASE WHEN jsonb_typeof(p->'usage'->'total_tokens')='number' AND p->'usage'->>'total_tokens' ~ '^[1-9][0-9]{0,6}$' THEN (p->'usage'->>'total_tokens')::numeric<=ec.token_ceiling ELSE false END\n    AND completion_state<>'INVALID',false);\n  FOR detail_name IN SELECT unnest(ARRAY['prompt_tokens_details','completion_tokens_details','server_tool_use']) LOOP\n    detail:=p->'usage'->detail_name;\n    IF detail IS NULL OR detail='null'::jsonb THEN CONTINUE; END IF;\n    IF jsonb_typeof(detail)<>'object' THEN valid_usage:=false; CONTINUE; END IF;\n    IF (SELECT count(*) FROM jsonb_object_keys(detail))>8 THEN valid_usage:=false; CONTINUE; END IF;\n    FOR detail_item IN SELECT key,value FROM jsonb_each(detail) LOOP\n      IF detail_item.key !~ '^[a-z][a-z0-9_]{0,63}$' OR jsonb_typeof(detail_item.value)<>'number'\n        OR detail_item.value#>>'{}' !~ '^(0|[1-9][0-9]{0,6})$' THEN valid_usage:=false;\n      ELSIF (detail_item.value#>>'{}')::numeric>8192\n        OR ((detail_name='server_tool_use' OR detail_item.key ~ '(reasoning|audio|tool)') AND detail_item.value<>'0'::jsonb) THEN valid_usage:=false; END IF;\n    END LOOP;\n  END LOOP;\n  FOR detail_name IN SELECT unnest(ARRAY['cost','cost_rub']) LOOP\n    raw_cost:=p->'usage'->detail_name;\n    IF raw_cost IS NULL THEN CONTINUE; END IF;\n    IF jsonb_typeof(raw_cost) NOT IN ('string','number') OR raw_cost#>>'{}' !~ '^(0|[1-9][0-9]{0,6})([.][0-9]{1,18})?([eE][+-]?[0-9]{1,3})?$' THEN valid_usage:=false; CONTINUE; END IF;\n    IF (raw_cost#>>'{}')::numeric>1000000 OR (reported_cost IS NOT NULL AND reported_cost<>(raw_cost#>>'{}')::numeric) THEN valid_usage:=false; END IF;\n    reported_cost:=(raw_cost#>>'{}')::numeric;\n  END LOOP;\n  IF reported_cost IS NOT NULL AND p->'cost'->>'status'='CONFIRMED' AND reported_cost<>(p->'cost'->>'amount')::numeric THEN valid_usage:=false; END IF;\n  IF p->>'kind'='SUCCESS' THEN\n    IF platform.knowledge_vectors_valid(p->'vectors',ec.input_count) IS NOT TRUE THEN validation:='INVALID_VECTOR';\n    ELSE vectors_hash:=encode(sha256(convert_to((p->'vectors')::text,'UTF8')),'hex'); END IF;\n    IF NOT valid_usage THEN validation:='USAGE_INVALID'; END IF;\n    IF p->'identity'->>'status'<>'CONFIRMED' OR p->'identity'->>'source' NOT IN ('BODY','HISTORY')\n      OR p->'identity'->>'provider' IS DISTINCT FROM 'OpenAI' OR p->'identity'->>'model' IS DISTINCT FROM 'openai/text-embedding-3-small'\n      OR p->'identity'->>'source'='HISTORY' AND p->'request_id'='null'::jsonb THEN validation:='IDENTITY_UNVERIFIED'; END IF;\n    IF p->'cost'->>'status'<>'CONFIRMED' THEN validation:='COST_UNKNOWN'; END IF;\n    IF p->'cost'->>'status'='CONFIRMED' AND (p->'cost'->>'amount')::numeric>ec.reserved_cost THEN validation:='COST_LIMIT'; END IF;\n  ELSIF p->'vectors'<>'null'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  record:=(p-'vectors')||jsonb_build_object('completion_tokens_state',completion_state,'validation_error',validation);\n  next_state:=CASE WHEN p->>'kind'='SUCCESS' AND validation IS NOT NULL THEN 'ERROR' ELSE p->>'kind' END;\n  IF ec.state<>'RESERVED' THEN\n    IF ec.outcome IS DISTINCT FROM record OR ec.vectors_sha256 IS DISTINCT FROM vectors_hash THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2801'; END IF;\n  ELSE\n    UPDATE platform.knowledge_embedding_calls SET state=next_state,outcome=record,completed_at=clock_timestamp(),vectors_sha256=vectors_hash WHERE id=ec.id RETURNING * INTO ec;\n    IF ec.kind='INDEX_BATCH' AND ec.state IN ('ERROR','UNKNOWN') THEN\n      UPDATE platform.knowledge_builds SET state=CASE WHEN ec.state='UNKNOWN' THEN 'UNKNOWN' ELSE 'ERROR' END,\n        error_code=CASE WHEN ec.state='UNKNOWN' THEN 'EMBEDDING_UNKNOWN' ELSE 'EMBEDDING_ERROR' END,version=version+1 WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.build_id;\n    END IF;\n  END IF;\n  RETURN jsonb_build_object('call_id',ec.id,'state',ec.state,'vectors_sha256',ec.vectors_sha256,'validation_error',ec.outcome->'validation_error',\n    'usage',ec.outcome->'usage','cost',ec.outcome->'cost','identity',ec.outcome->'identity','completion_tokens_state',ec.outcome->'completion_tokens_state');\nEND $$",
    "platform.ai_runtime_config_valid(jsonb)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_config_valid(p jsonb) RETURNS boolean\nLANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nSELECT (p->>'prompt_revision'='conversation_v4' AND platform.ai_synthetic_config_valid(jsonb_set(p,'{prompt_revision}','\"conversation_v2\"'::jsonb))) OR platform.ai_synthetic_config_valid(p) OR platform.ai_provider_config_valid(p) OR\n  (p->>'prompt_revision'='conversation_v3' AND\n    platform.ai_synthetic_config_valid(jsonb_set(p,'{prompt_revision}','\"conversation_v2\"'::jsonb))) $$",
    "platform.ai_runtime_command(uuid,uuid,text,jsonb)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_command(p_job uuid,p_claim uuid,p_op text,p jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE j platform.messaging_jobs%ROWTYPE; r platform.ai_runs%ROWTYPE; previous platform.ai_provider_calls%ROWTYPE;\n        fresh jsonb; knowledge jsonb; search jsonb; b jsonb; cfg jsonb; lim jsonb; expiry timestamptz; next_job uuid; n integer; tokens integer; cost numeric;\n      BEGIN\n        PERFORM platform.turn_require_isolation();\n        j:=platform.messaging_guard(p_job,p_claim);\n        IF current_database() NOT IN ('asm_local','asm_test') OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>32768 THEN\n          RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF p_op='ENQUEUE' THEN\n          IF j.kind<>'PROCESS_TURN' OR j.step<>'TEST_CONSUME' OR p<>'{}'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          PERFORM platform.ai_runtime_current(j,NULL);\n          INSERT INTO platform.messaging_jobs(workspace_id,connection_id,kind,turn_id,turn_revision,step,correlation_id)\n            VALUES(j.workspace_id,j.connection_id,'PROCESS_TURN',j.turn_id,j.turn_revision,'AI_GENERATE',j.correlation_id)\n            ON CONFLICT(workspace_id,turn_id,turn_revision,step) DO NOTHING;\n          SELECT id INTO STRICT next_job FROM platform.messaging_jobs WHERE workspace_id=j.workspace_id AND turn_id=j.turn_id AND turn_revision=j.turn_revision AND step='AI_GENERATE';\n          RETURN jsonb_build_object('job_id',next_job);\n        END IF;\n        IF j.kind<>'PROCESS_TURN' OR j.step<>'AI_GENERATE' THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        SELECT * INTO r FROM platform.ai_runs WHERE workspace_id=j.workspace_id AND job_id=j.id FOR UPDATE;\n        IF p_op='PREPARE' THEN\n          cfg:=p->'config';\n          IF NOT platform.material_object(p,ARRAY['config','deadline']) OR jsonb_typeof(p->'deadline') IS DISTINCT FROM 'string'\n            OR platform.ai_runtime_config_valid(cfg) IS NOT TRUE OR cfg->>'prompt_revision' NOT IN ('conversation_v3','conversation_v4') THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF r.id IS NOT NULL AND r.config IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n          BEGIN fresh:=platform.ai_runtime_current(j,r.snapshot);\n          EXCEPTION WHEN SQLSTATE 'P2001' THEN\n            IF r.id IS NOT NULL AND SQLERRM='AI_STALE' THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n            RAISE;\n          END;\n          IF cfg->'route'->>'execution'='PROVIDER' THEN\n            PERFORM platform.ai_provider_guard((SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id),j,cfg);\n          ELSIF (SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id) IS NOT NULL THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          IF r.id IS NOT NULL THEN\n            IF fresh->'binding' IS DISTINCT FROM r.binding OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n            RETURN platform.ai_runtime_view(r);\n          END IF;\n          expiry:=least((p->>'deadline')::timestamptz,clock_timestamp()+(cfg->'limits'->>'duration_seconds')::numeric*interval '1 second');\n          IF NOT isfinite(expiry) OR expiry<=clock_timestamp() THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          b:=fresh->'binding';\n          knowledge:=platform.ai_knowledge_snapshot(j.workspace_id,(b->>'business_id')::uuid);\n          search:=CASE WHEN cfg->>'prompt_revision'='conversation_v4' THEN platform.knowledge_availability(j.workspace_id,(b->>'business_id')::uuid,(knowledge->'knowledge_pin'->>'release_id')::uuid,(knowledge->'knowledge_pin'->>'activation_version')::bigint) END;\n          INSERT INTO platform.ai_runs(workspace_id,job_id,connection_id,conversation_id,client_id,business_id,turn_id,turn_revision,\n            resume_receipt_id,control_generation,binding,snapshot,snapshot_digest,storage_fingerprint,config,config_fingerprint,deadline,knowledge_pin,active_projection,search_pin)\n          VALUES(j.workspace_id,j.id,j.connection_id,(b->>'conversation_id')::uuid,(b->>'client_id')::uuid,(b->>'business_id')::uuid,j.turn_id,j.turn_revision,\n            (b->>'resume_receipt_id')::uuid,(b->>'control_generation')::bigint,b,fresh->'snapshot',b->>'snapshot_digest',encode(sha256(convert_to((fresh->'snapshot')::text,'UTF8')),'hex'),cfg,encode(sha256(convert_to(cfg::text,'UTF8')),'hex'),expiry,knowledge->'knowledge_pin',knowledge->'active_projection',search) RETURNING * INTO r;\n          RETURN platform.ai_runtime_view(r);\n        END IF;\n        IF r.id IS NULL OR p->>'run_id' IS DISTINCT FROM r.id::text THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF p_op='COMPLETE' THEN\n          IF NOT platform.material_object(p,ARRAY['run_id','sequence','completion']) OR platform.ai_runtime_completion_valid(p->'completion') IS NOT TRUE THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          SELECT * INTO previous FROM platform.ai_provider_calls WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=(p->>'sequence')::int FOR UPDATE;\n          IF previous.claim_hash IS DISTINCT FROM sha256(convert_to(p_claim::text,'UTF8')) OR previous.attempt_count IS DISTINCT FROM j.attempt_count THEN\n            RAISE EXCEPTION 'STALE_CLAIM' USING ERRCODE='P2001'; END IF;\n          IF previous.completed_at IS NOT NULL THEN\n            IF previous.completion IS DISTINCT FROM p->'completion' THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n          ELSE\n            UPDATE platform.ai_provider_calls SET completion=p->'completion',completed_at=clock_timestamp()\n              WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=previous.sequence;\n          END IF;\n          RETURN jsonb_build_object('recorded',true);\n        END IF;\n        fresh:=platform.ai_runtime_current(j,r.snapshot);\n        IF fresh->'binding' IS DISTINCT FROM r.binding OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        IF r.deadline<=clock_timestamp() OR r.result IS NOT NULL THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF r.config->'route'->>'execution'='PROVIDER' THEN\n          PERFORM platform.ai_provider_guard((SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id),j,r.config);\n        END IF;\n        IF r.config->>'prompt_revision'='conversation_v4' AND r.search_refs IS NULL THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n        lim:=r.config->'limits';\n        SELECT * INTO previous FROM platform.ai_provider_calls WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=r.calls_used;\n        IF p_op IN ('AUTHORIZE','READ') THEN\n          IF p->'binding' IS DISTINCT FROM r.binding OR p->'knowledge_pin' IS DISTINCT FROM r.knowledge_pin OR (r.config->>'prompt_revision'='conversation_v4' AND p->'search_pin' IS DISTINCT FROM r.search_pin) THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n          IF (p_op='AUTHORIZE' AND (NOT platform.material_object(p,ARRAY['run_id','binding','knowledge_pin','boundary']||CASE WHEN r.config->>'prompt_revision'='conversation_v4' THEN ARRAY['search_pin'] ELSE ARRAY[]::text[] END) OR p->>'boundary' NOT IN ('MODEL','READ','FOLLOWUP','CANDIDATE')))\n            OR (p_op='READ' AND NOT platform.material_object(p,ARRAY['run_id','binding','knowledge_pin']||CASE WHEN r.config->>'prompt_revision'='conversation_v4' THEN ARRAY['search_pin'] ELSE ARRAY[]::text[] END)) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF p->>'boundary'='MODEL' AND r.calls_used<>0 THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          IF p_op='READ' OR p->>'boundary' IN ('READ','FOLLOWUP') THEN\n            IF r.calls_used<>1 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'TOOLS'\n              OR (lim->>'read_executions')::int<1 THEN RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n            IF (p_op='READ' OR p->>'boundary'='READ') AND r.reads_used<>0 OR p->>'boundary'='FOLLOWUP' AND r.reads_used<>1 THEN\n              RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          END IF;\n          IF p->>'boundary'='CANDIDATE' AND (r.calls_used=0 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'OUTPUT') THEN\n            RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          IF p_op='READ' THEN\n            UPDATE platform.ai_runs SET reads_used=1,read_audit=jsonb_build_object('outcome','READ','context_version',r.binding->'context_version',\n              'turn_revision',r.turn_revision,'native',r.binding->'native','knowledge_pin',r.knowledge_pin,'at',clock_timestamp())||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin_sha256',encode(sha256(convert_to(r.search_pin::text,'UTF8')),'hex')) ELSE '{}'::jsonb END WHERE workspace_id=j.workspace_id AND id=r.id;\n            RETURN jsonb_build_object('binding',r.binding,'snapshot',r.snapshot,\n              'knowledge_pin',r.knowledge_pin,'active_projection',r.active_projection)\n              ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs,'search_projection',platform.knowledge_projection(r)) ELSE '{}'::jsonb END;\n          END IF;\n          RETURN jsonb_build_object('allowed',true);\n        ELSIF p_op='RESERVE' THEN\n          b:=p->'budget'; n:=r.calls_used+1;\n          IF NOT platform.material_object(p,ARRAY['run_id','budget']) OR NOT platform.material_object(b,ARRAY['calls_used','reads_reserved','tokens_reserved','cost_reserved','currency'])\n            OR jsonb_typeof(b->'calls_used')<>'number' OR jsonb_typeof(b->'reads_reserved')<>'number' OR jsonb_typeof(b->'tokens_reserved')<>'number' THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          tokens:=(b->>'tokens_reserved')::int; cost:=(b->>'cost_reserved')::numeric;\n          IF n>2 OR n>(lim->>'model_calls')::int OR (b->>'calls_used')::int<>n OR (b->>'reads_reserved')::int<>r.reads_used\n            OR b->>'currency' IS DISTINCT FROM lim->>'currency' OR tokens<=r.tokens_reserved OR tokens>(lim->>'total_tokens')::int\n            OR tokens-r.tokens_reserved>(lim->>'input_tokens')::int+(lim->>'output_tokens')::int\n            OR cost<>r.cost_reserved+(lim->>'call_cost_reservation')::numeric OR cost>(lim->>'cost_budget')::numeric\n            OR (n=2 AND (r.reads_used<>1 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'TOOLS')) THEN\n            RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          IF r.config->'route'->>'execution'='PROVIDER' AND EXISTS(\n            SELECT 1 FROM platform.ai_provider_sessions s WHERE s.id=(SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id) AND\n            (EXISTS(SELECT 1 FROM platform.ai_provider_calls pc JOIN platform.ai_runs ar ON (ar.workspace_id,ar.id)=(pc.workspace_id,pc.run_id)\n              JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(ar.workspace_id,ar.job_id)\n              WHERE d.provider_session_id=s.id AND (pc.completed_at IS NULL OR pc.completion->>'kind'='UNKNOWN'\n                OR pc.completion->'cost'->>'status'='UNKNOWN'\n                OR (pc.completion->'cost'->>'amount')::numeric>(ar.config->'limits'->>'call_cost_reservation')::numeric))\n            OR (SELECT count(*) FROM platform.ai_provider_calls pc JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(pc.workspace_id,(SELECT job_id FROM platform.ai_runs WHERE workspace_id=pc.workspace_id AND id=pc.run_id)) WHERE d.provider_session_id=s.id)>=s.max_calls\n            OR (SELECT coalesce(sum(greatest((ar.config->'limits'->>'call_cost_reservation')::numeric,coalesce((pc.completion->'cost'->>'amount')::numeric,0))),0)\n              FROM platform.ai_provider_calls pc JOIN platform.ai_runs ar ON (ar.workspace_id,ar.id)=(pc.workspace_id,pc.run_id)\n              JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(ar.workspace_id,ar.job_id) WHERE d.provider_session_id=s.id)\n              +(lim->>'call_cost_reservation')::numeric>s.max_rub)) THEN\n            RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          INSERT INTO platform.ai_provider_calls(workspace_id,run_id,sequence,claim_hash,attempt_count,budget)\n            VALUES(j.workspace_id,r.id,n,sha256(convert_to(p_claim::text,'UTF8')),j.attempt_count,b);\n          UPDATE platform.ai_runs SET calls_used=n,tokens_reserved=tokens,cost_reserved=cost WHERE workspace_id=j.workspace_id AND id=r.id;\n          RETURN jsonb_build_object('sequence',n);\n        ELSIF p_op='COMMIT' THEN\n          IF NOT platform.material_object(p,ARRAY['run_id','result']) OR platform.ai_runtime_result_valid(p->'result') IS NOT TRUE THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF r.calls_used=0 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'OUTPUT' THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          PERFORM platform.messaging_guard(p_job,p_claim);\n          UPDATE platform.ai_runs SET result=p->'result',selected_at=clock_timestamp(),winning_claim_hash=sha256(convert_to(p_claim::text,'UTF8'))\n            WHERE workspace_id=j.workspace_id AND id=r.id AND result IS NULL RETURNING * INTO r;\n          PERFORM platform.ai_delivery_select(j,r);\n          UPDATE platform.messaging_jobs SET status='SUCCEEDED',turn_outcome='OBSERVED',error_code=NULL,claim_token=NULL,lease_until=NULL,\n            worker_id=NULL,completed_at=clock_timestamp(),version=version+1 WHERE id=j.id;\n          RETURN platform.ai_runtime_receipt(r);\n        END IF;\n        RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001';\n      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format OR datetime_field_overflow THEN\n        RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001';\n      END $$",
    "platform.ai_runtime_view(platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_view(r platform.ai_runs) RETURNS jsonb\n      LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      SELECT jsonb_build_object('run_id',r.id,'binding',r.binding,'snapshot',r.snapshot,'storage_fingerprint',r.storage_fingerprint,\n        'config',r.config,'deadline',r.deadline,'reads_used',r.reads_used,'budget',jsonb_build_object(\n          'calls_used',r.calls_used,'reads_reserved',r.reads_used,'tokens_reserved',r.tokens_reserved,\n          'cost_reserved',r.cost_reserved::text,'currency',r.config->'limits'->>'currency'))\n        ||CASE WHEN r.knowledge_pin IS NULL THEN '{}'::jsonb ELSE\n          jsonb_build_object('knowledge_pin',r.knowledge_pin,'active_projection',r.active_projection) END\n        ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs) ELSE '{}'::jsonb END $$",
    "platform.ai_runtime_receipt(platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_receipt(r platform.ai_runs) RETURNS jsonb\n      LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      SELECT jsonb_build_object('run_id',r.id,'job_id',r.job_id,'turn_id',r.turn_id,'turn_revision',r.turn_revision,\n        'selected_at',r.selected_at,'result',r.result,'send_permit',false)\n        ||CASE WHEN r.knowledge_pin IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('knowledge_pin',r.knowledge_pin) END\n        ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs) ELSE '{}'::jsonb END $$",
    "platform.knowledge_runtime_current(platform.ai_runs)": "CREATE FUNCTION platform.knowledge_runtime_current(r platform.ai_runs) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE j platform.messaging_jobs%ROWTYPE; state platform.business_configuration_state%ROWTYPE;\nBEGIN\n  IF r.config->>'prompt_revision'<>'conversation_v4' THEN RETURN true; END IF;\n  j:=platform.messaging_guard(nullif(current_setting('asm.job_id',true),'')::uuid,nullif(current_setting('asm.claim_token',true),'')::uuid);\n  IF j.workspace_id<>r.workspace_id OR j.connection_id<>r.connection_id THEN RETURN false; END IF;\n  PERFORM pg_advisory_xact_lock(hashtextextended(r.workspace_id::text||':'||r.business_id::text||'|CONFIGURATION_V1',2018));\n  SELECT * INTO state FROM platform.business_configuration_state WHERE workspace_id=r.workspace_id AND business_id=r.business_id;\n  RETURN r.search_pin IS NOT NULL AND r.search_pin=platform.knowledge_availability(r.workspace_id,r.business_id,state.active_release_id,coalesce(state.activation_version,0));\nEND $$",
    "platform.ai_delivery_select(platform.messaging_jobs,platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_delivery_select(j platform.messaging_jobs,r platform.ai_runs) RETURNS void\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE d platform.ai_deliveries%ROWTYPE; c app.conversations%ROWTYPE; conn app.channel_connections%ROWTYPE;\n        msg uuid; box uuid; send uuid; intent_context bigint; e jsonb;\n      BEGIN\n        SELECT * INTO d FROM platform.ai_deliveries WHERE workspace_id=j.workspace_id AND job_id=j.id FOR UPDATE;\n        IF NOT FOUND THEN RETURN; END IF; -- historical DB-only run: no retroactive intent\n        IF d.selected_kind IS NOT NULL OR r.result IS NULL OR r.winning_claim_hash IS DISTINCT FROM sha256(convert_to(j.claim_token::text,'UTF8')) THEN\n          RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n        PERFORM platform.ai_runtime_current(j,r.snapshot);\n        IF platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        SELECT * INTO STRICT c FROM app.conversations WHERE workspace_id=j.workspace_id AND id=r.conversation_id;\n        SELECT * INTO STRICT conn FROM app.channel_connections WHERE workspace_id=j.workspace_id AND id=j.connection_id;\n        IF r.result->>'kind'='reply' THEN\n          IF conn.provider='TELEGRAM' AND platform.telegram_can_send(j.workspace_id,j.connection_id,c.id,false) IS NOT TRUE THEN\n            RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          INSERT INTO app.messages(workspace_id,conversation_id,connection_id,provider_chat_id,direction,content_type,text,occurred_at)\n            VALUES(j.workspace_id,c.id,j.connection_id,c.provider_chat_id,'OUTBOUND','TEXT',r.result->>'text',clock_timestamp()) RETURNING id INTO msg;\n          SELECT version INTO STRICT intent_context FROM app.conversations WHERE workspace_id=j.workspace_id AND id=c.id;\n          IF intent_context::numeric<>(r.binding->>'context_version')::numeric+1 THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n          INSERT INTO app.outbox_events(workspace_id,connection_id,message_id,kind)\n            VALUES(j.workspace_id,j.connection_id,msg,'SEND_AI_TEXT') RETURNING id INTO box;\n          INSERT INTO platform.messaging_jobs(workspace_id,connection_id,kind,outbox_id,correlation_id)\n            VALUES(j.workspace_id,j.connection_id,'SEND_AI_TEXT',box,j.correlation_id) RETURNING id INTO send;\n        ELSIF r.result->>'kind'='handoff' THEN\n          e:=platform.escalation_request_for_turn(j.id,j.claim_token);\n          IF e->>'code' IS DISTINCT FROM 'ESCALATED' THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        END IF;\n        IF j.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'STALE_CLAIM' USING ERRCODE='P2001'; END IF;\n        UPDATE platform.ai_deliveries SET knowledge_pin=r.knowledge_pin,search_pin=r.search_pin,run_id=r.id,selected_kind=r.result->>'kind',message_id=msg,outbox_id=box,send_job_id=send,\n          intent_context_version=intent_context,escalation_id=(e->>'escalation_id')::uuid WHERE workspace_id=j.workspace_id AND job_id=j.id;\n      END $$",
    "platform.ai_delivery_current(platform.messaging_jobs,platform.ai_deliveries,platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_delivery_current(j platform.messaging_jobs,d platform.ai_deliveries,r platform.ai_runs) RETURNS boolean\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE t app.conversation_turns%ROWTYPE; c app.conversations%ROWTYPE; resume platform.conversation_control_receipts%ROWTYPE;\n        allowed boolean;\n      BEGIN\n        SELECT * INTO STRICT resume FROM platform.conversation_control_receipts WHERE workspace_id=j.workspace_id AND id=r.resume_receipt_id;\n        IF platform.messaging_lock_owner(j.workspace_id,resume.actor_user_account_id) IS NOT TRUE THEN RETURN false; END IF;\n        PERFORM 1 FROM app.businesses WHERE (workspace_id,id)=(j.workspace_id,r.business_id) AND status='ACTIVE' FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(j.workspace_id::text||':'||r.business_id::text||'|CONFIGURATION_V1',2018));\n        IF r.knowledge_pin IS NULL OR d.knowledge_pin IS DISTINCT FROM r.knowledge_pin OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE OR d.search_pin IS DISTINCT FROM r.search_pin THEN RETURN false; END IF;\n        PERFORM 1 FROM app.channel_connections WHERE (workspace_id,id,business_id)=(j.workspace_id,j.connection_id,r.business_id)\n          AND status='ACTIVE' AND (provider='CONTROLLED' OR (current_database()='asm_test' AND provider='TELEGRAM')) FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM platform.messaging_lock_billing_workspace(j.workspace_id);\n        SELECT * INTO STRICT c FROM app.conversations WHERE workspace_id=j.workspace_id AND id=r.conversation_id FOR NO KEY UPDATE;\n        SELECT * INTO STRICT t FROM app.conversation_turns WHERE workspace_id=j.workspace_id AND id=r.turn_id FOR NO KEY UPDATE;\n        PERFORM 1 FROM app.clients WHERE (workspace_id,id)=(j.workspace_id,r.client_id) FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM platform.messaging_guard(j.id,j.claim_token);\n        IF (c.client_id,c.business_id,c.connection_id,c.version,t.revision,t.state,t.control_generation,t.activation_fence_seq) IS DISTINCT FROM\n          (r.client_id,r.business_id,r.connection_id,d.intent_context_version,r.turn_revision,'READY',r.control_generation,(r.binding->>'activation_fence_seq')::bigint)\n          OR (resume.operation,resume.conversation_id,resume.client_id,resume.accepted_generation,resume.activation_fence_seq) IS DISTINCT FROM\n            ('RESUME',c.id,c.client_id,t.control_generation,t.activation_fence_seq)\n          OR platform.conversation_turn_activation_matches(j.workspace_id,t.id) IS NOT TRUE\n          OR platform.material_turn_usable(j.workspace_id,t.id) IS NOT TRUE\n          OR platform.human_context_admission(j.workspace_id,c.id,r.snapshot-'code'-'job_id') IS DISTINCT FROM 'CURRENT'\n          OR EXISTS(SELECT 1 FROM app.escalations WHERE workspace_id=j.workspace_id AND conversation_id=c.id AND status='PENDING') THEN RETURN false; END IF;\n        BEGIN allowed:=platform.messaging_manual_send_allowed(j.workspace_id);\n        EXCEPTION WHEN SQLSTATE 'P2301' THEN RETURN false; END;\n        IF d.provider_session_id IS NOT NULL AND allowed IS TRUE THEN\n          BEGIN PERFORM platform.ai_provider_guard(d.provider_session_id,j,r.config);\n          EXCEPTION WHEN SQLSTATE 'P2001' THEN RETURN false; END;\n        END IF;\n        RETURN allowed IS TRUE;\n      END $$",
    "platform.ai_delivery_immutable()": "CREATE OR REPLACE FUNCTION platform.ai_delivery_immutable() RETURNS trigger\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      BEGIN\n        IF OLD.selected_kind IS NOT NULL OR\n          (to_jsonb(OLD)-ARRAY['search_pin','knowledge_pin','run_id','selected_kind','message_id','outbox_id','send_job_id','escalation_id','intent_context_version']) IS DISTINCT FROM\n          (to_jsonb(NEW)-ARRAY['search_pin','knowledge_pin','run_id','selected_kind','message_id','outbox_id','send_job_id','escalation_id','intent_context_version']) OR\n          NOT EXISTS(SELECT 1 FROM platform.ai_runs r WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.run_id AND r.job_id=NEW.job_id AND r.result->>'kind'=NEW.selected_kind AND r.knowledge_pin IS NOT NULL AND r.knowledge_pin=NEW.knowledge_pin AND r.search_pin IS NOT DISTINCT FROM NEW.search_pin) THEN\n          RAISE EXCEPTION 'immutable AI delivery' USING ERRCODE='23514'; END IF;\n        RETURN NEW;\n      END $$",
    "platform.human_context_policy_command(uuid,uuid,text,text,text,bigint,jsonb,jsonb)": "CREATE OR REPLACE FUNCTION platform.human_context_policy_command(ws uuid,p_connection uuid,p_operation text,p_key text,\n        p_expected_policy text,p_expected_epoch bigint,p_binding jsonb,p_profile jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE c app.channel_connections%ROWTYPE; s platform.telegram_connection_state%ROWTYPE;\n        r platform.human_context_policy_receipts%ROWTYPE; prior platform.human_context_policy_receipts%ROWTYPE;\n        profile jsonb; fingerprint bytea; binding jsonb; allowed boolean; moment timestamptz; corr uuid;\n      BEGIN\n        IF session_user<>'asm_migrator' OR current_database() NOT IN ('asm_local','asm_test') THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2601'; END IF;\n        PERFORM platform.turn_require_isolation();\n        IF ws IS NULL OR p_connection IS NULL OR p_operation IS NULL OR p_operation NOT IN ('ENABLE','PAUSE') OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$'\n          OR p_expected_policy IS NULL OR p_expected_policy NOT IN ('OFF_UNUSED','ON','PAUSED') OR p_expected_epoch IS NULL OR p_expected_epoch<0\n          OR platform.material_object(p_binding,ARRAY['business_id','provider','bot_identity','external_connection_id','owner_user_id']) IS NOT TRUE\n          OR platform.material_object(p_profile,ARRAY['source_tree','schema_revision','profile_sha256','drain_confirmed']) IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2601'; END IF;\n        IF NOT platform.human_context_uuid(p_binding->'business_id') OR jsonb_typeof(p_binding->'provider')<>'string' OR p_binding->>'provider' NOT IN ('CONTROLLED','TELEGRAM')\n          OR jsonb_typeof(p_binding->'bot_identity')<>'string' OR platform.messaging_valid_id(p_binding->>'bot_identity',128,512) IS NOT TRUE\n          OR jsonb_typeof(p_binding->'external_connection_id')<>'string' OR platform.messaging_valid_id(p_binding->>'external_connection_id',256,1024) IS NOT TRUE\n          OR NOT ((p_binding->>'provider'='CONTROLLED' AND p_binding->'owner_user_id'='null'::jsonb) OR\n            (p_binding->>'provider'='TELEGRAM' AND jsonb_typeof(p_binding->'owner_user_id')='string' AND platform.telegram_numeric_id(p_binding->>'owner_user_id') IS TRUE\n              AND platform.telegram_numeric_id(p_binding->>'bot_identity') IS TRUE))\n          OR jsonb_typeof(p_profile->'source_tree')<>'string' OR p_profile->>'source_tree' !~ '^[0-9a-f]{40}$'\n          OR jsonb_typeof(p_profile->'schema_revision')<>'string' OR p_profile->>'schema_revision'<>'0020'\n          OR jsonb_typeof(p_profile->'profile_sha256')<>'string' OR p_profile->>'profile_sha256' !~ '^[0-9a-f]{64}$'\n          OR p_profile->'drain_confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2601'; END IF;\n        SELECT platform.knowledge_search_schema_profile() INTO profile;\n        IF profile->'valid' IS DISTINCT FROM 'true'::jsonb OR p_profile->>'profile_sha256' IS DISTINCT FROM profile->>'profile_sha256' THEN\n          RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n        PERFORM 1 FROM platform.workspaces WHERE id=ws FOR SHARE;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(ws::text||':HUMAN_CONTEXT_POLICY_V1:'||p_key,2013));\n        SELECT * INTO c FROM app.channel_connections WHERE workspace_id=ws AND id=p_connection;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        PERFORM 1 FROM app.businesses WHERE workspace_id=ws AND id=c.business_id FOR SHARE;\n        SELECT * INTO STRICT c FROM app.channel_connections WHERE workspace_id=ws AND id=p_connection FOR UPDATE;\n        SELECT * INTO s FROM platform.telegram_connection_state WHERE workspace_id=ws AND connection_id=c.id FOR SHARE;\n        binding:=jsonb_build_object('business_id',c.business_id,'provider',c.provider,'bot_identity',c.bot_identity,\n          'external_connection_id',c.external_connection_id,'owner_user_id',CASE WHEN c.provider='TELEGRAM' THEN s.owner_user_id END);\n        IF binding IS DISTINCT FROM p_binding OR NOT EXISTS(SELECT 1 FROM platform.channel_routes WHERE workspace_id=ws AND connection_id=c.id\n          AND provider=c.provider AND bot_identity=c.bot_identity AND route_key=c.external_connection_id) OR\n          (c.provider='TELEGRAM' AND (s.bot_identity,s.external_connection_id,s.owner_user_id) IS DISTINCT FROM\n            (c.bot_identity,c.external_connection_id,p_binding->>'owner_user_id')) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        SELECT platform.knowledge_search_schema_profile() INTO profile;\n        IF session_user<>'asm_migrator' OR profile->'valid' IS DISTINCT FROM 'true'::jsonb OR p_profile->>'profile_sha256' IS DISTINCT FROM profile->>'profile_sha256' THEN\n          RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n        fingerprint:=platform.human_context_hash(E'asm:m3:human_context_policy:v1\\n',ARRAY[ws::text,session_user::text,c.id::text,p_operation,p_expected_policy,p_expected_epoch::text,\n          p_binding->>'business_id',p_binding->>'provider',p_binding->>'bot_identity',p_binding->>'external_connection_id',p_binding->>'owner_user_id',\n          p_profile->>'source_tree',p_profile->>'schema_revision',p_profile->>'profile_sha256','true']);\n        SELECT * INTO prior FROM platform.human_context_policy_receipts WHERE workspace_id=ws AND namespace='HUMAN_CONTEXT_POLICY_V1' AND idempotency_key=p_key;\n        IF FOUND THEN\n          IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2601'; END IF;\n          RETURN jsonb_build_object('outcome','REPLAY','result',prior.result);\n        END IF;\n        IF (c.human_context_policy,c.human_context_policy_epoch) IS DISTINCT FROM (p_expected_policy,p_expected_epoch) THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2601'; END IF;\n        IF p_operation='PAUSE' AND c.human_context_policy='OFF_UNUSED' THEN RAISE EXCEPTION 'CONTEXT_POLICY_INACTIVE' USING ERRCODE='P2601'; END IF;\n        IF p_operation='ENABLE' THEN\n          IF NOT EXISTS(SELECT 1 FROM platform.workspaces WHERE id=ws AND status='ACTIVE')\n            OR NOT EXISTS(SELECT 1 FROM app.businesses WHERE workspace_id=ws AND id=c.business_id AND status='ACTIVE') OR c.status<>'ACTIVE'\n            OR (c.provider='TELEGRAM' AND s.material_enabled IS NOT TRUE) THEN RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n          BEGIN allowed:=platform.messaging_manual_send_allowed(ws);\n            EXCEPTION WHEN SQLSTATE 'P2301' THEN RAISE EXCEPTION 'UNAVAILABLE' USING ERRCODE='P2601'; END;\n          IF allowed IS NOT TRUE THEN RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n          IF c.human_context_policy='PAUSED' AND c.human_context_policy_epoch=9223372036854775807 THEN\n            RAISE EXCEPTION 'POLICY_VERSION_EXHAUSTED' USING ERRCODE='P2601'; END IF;\n        END IF;\n        r.workspace_id:=ws; r.id:=uuidv7(); r.connection_id:=c.id; r.business_id:=c.business_id; r.provider:=c.provider;\n        r.bot_identity:=c.bot_identity; r.external_connection_id:=c.external_connection_id; r.owner_user_id:=p_binding->>'owner_user_id';\n        r.actor_db_role:=session_user; r.namespace:='HUMAN_CONTEXT_POLICY_V1'; r.idempotency_key:=p_key; r.request_fingerprint:=fingerprint;\n        r.operation:=p_operation; r.expected_policy:=p_expected_policy; r.expected_policy_epoch:=p_expected_epoch;\n        r.accepted_policy:=CASE WHEN p_operation='ENABLE' THEN 'ON' ELSE 'PAUSED' END;\n        r.accepted_policy_epoch:=p_expected_epoch+CASE WHEN p_operation='ENABLE' AND p_expected_policy<>'ON' THEN 1 ELSE 0 END;\n        r.change:=CASE WHEN r.accepted_policy=p_expected_policy THEN 'UNCHANGED' WHEN p_operation='ENABLE' THEN 'ENABLED' ELSE 'PAUSED' END;\n        r.source_profile:=p_profile; r.event_type:='HUMAN_CONTEXT_POLICY_COMMANDED'; r.accepted_at:=clock_timestamp(); corr:=uuidv7();\n        INSERT INTO app.audit_events(workspace_id,actor_kind,actor_user_account_id,correlation_id,event_type,object_type,object_id,object_version,payload)\n          VALUES(ws,'LOCAL_PROVISIONER',NULL,corr,r.event_type,'CHANNEL_CONNECTION',c.id,r.accepted_policy_epoch,\n            jsonb_build_object('receipt_id',r.id,'operation',r.operation,'change',r.change,'previous_policy',r.expected_policy,'accepted_policy',r.accepted_policy,\n              'previous_policy_epoch',r.expected_policy_epoch::text,'accepted_policy_epoch',r.accepted_policy_epoch::text)) RETURNING audit_event_id INTO r.audit_event_id;\n        r.result:=platform.human_context_policy_result(r);\n        INSERT INTO platform.human_context_policy_receipts SELECT r.*;\n        IF r.change<>'UNCHANGED' THEN UPDATE app.channel_connections SET human_context_policy=r.accepted_policy,\n          human_context_policy_epoch=r.accepted_policy_epoch WHERE workspace_id=ws AND id=c.id; END IF;\n        RETURN jsonb_build_object('outcome','ACCEPTED','result',r.result);\n      END $$",
}

REPLACEMENTS = {
    "platform.ai_provider_session(jsonb,boolean)": "CREATE OR REPLACE FUNCTION platform.ai_provider_session(p jsonb,p_enable boolean) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE s platform.ai_provider_sessions%ROWTYPE; old platform.ai_provider_sessions%ROWTYPE;\nBEGIN\n  IF session_user<>'asm_migrator' OR current_database()<>'asm_test' OR p_enable IS NULL THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  IF p_enable IS FALSE THEN\n    IF NOT platform.material_object(p,ARRAY['session_id']) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n    UPDATE platform.ai_provider_sessions SET active=false WHERE id=(p->>'session_id')::uuid;\n    IF NOT FOUND THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n    RETURN jsonb_build_object('code','DISABLED');\n  END IF;\n  IF NOT platform.material_object(p,ARRAY['session_id','workspace_id','connection_id','conversation_id','client_id','chat_id','bot_identity','data_profile','starts_at','expires_at','max_calls','max_rub','review_sha256','review_checked_at','config'])\n    OR platform.ai_provider_config_valid(p->'config') IS NOT TRUE\n    OR (p->>'data_profile',p->'config'->>'prompt_revision') NOT IN\n      (('SYNTHETIC_TEXT_V1','conversation_v2'),('SYNTHETIC_PUBLISHED_KNOWLEDGE_V1','conversation_v3'))\n    OR p->'config'->>'revision' IS DISTINCT FROM 'polza-'||(p->>'session_id')||'-'||(p->>'review_sha256')\n    OR (platform.portfolio_schema_profile()->>'valid')::boolean IS NOT TRUE THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  s:=jsonb_populate_record(NULL::platform.ai_provider_sessions,(p-'session_id')||jsonb_build_object('id',p->>'session_id','active',true,'created_at',clock_timestamp()));\n  IF s.starts_at>clock_timestamp() OR s.expires_at<=clock_timestamp() OR s.review_checked_at>clock_timestamp()\n    OR s.review_checked_at<clock_timestamp()-interval '24 hours'\n    OR (s.config->'limits'->>'call_cost_reservation')::numeric*s.max_calls>s.max_rub\n    OR NOT EXISTS(SELECT 1 FROM app.conversations c JOIN app.channel_connections cc ON (cc.workspace_id,cc.id)=(c.workspace_id,c.connection_id)\n      WHERE (c.workspace_id,c.id,c.connection_id,c.client_id,c.provider_chat_id)=(s.workspace_id,s.conversation_id,s.connection_id,s.client_id,s.chat_id)\n      AND cc.provider='TELEGRAM' AND cc.bot_identity=s.bot_identity AND cc.status='ACTIVE') THEN\n    RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n  SELECT * INTO old FROM platform.ai_provider_sessions WHERE id=s.id FOR UPDATE;\n  IF FOUND THEN\n    IF (to_jsonb(old)-'created_at') IS DISTINCT FROM (to_jsonb(s)-'created_at') THEN\n      RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n    RETURN jsonb_build_object('code','ALREADY_ENABLED');\n  END IF;\n  INSERT INTO platform.ai_provider_sessions SELECT s.*;\n  RETURN jsonb_build_object('code','ENABLED');\nEND $$",
    "platform.configuration_command(uuid,text,text,jsonb)": "CREATE OR REPLACE FUNCTION platform.configuration_command(p_business uuid,p_operation text,p_key text,p jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE ws uuid; actor uuid; corr uuid; fingerprint bytea; prior platform.business_configuration_receipts%ROWTYPE;\n        s platform.business_configuration_state%ROWTYPE; r platform.business_configuration_releases%ROWTYPE;\n        current_body jsonb; v jsonb; result jsonb; receipt uuid; moment timestamptz; expected bigint;\n      BEGIN\n        PERFORM platform.turn_require_isolation(); ws:=app.current_workspace_id(); actor:=nullif(current_setting('asm.actor_id',true),'')::uuid;\n        IF ws IS NULL OR platform.messaging_lock_owner(ws,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2701'; END IF;\n        PERFORM 1 FROM app.businesses WHERE workspace_id=ws AND id=p_business AND status='ACTIVE' FOR SHARE;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2701'; END IF;\n        IF p_operation IS NULL OR p_operation NOT IN ('EDIT','PUBLISH','ROLLBACK') OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$'\n          OR platform.material_object(p,CASE p_operation WHEN 'EDIT' THEN ARRAY['expected_draft_version','bundle']\n            WHEN 'PUBLISH' THEN ARRAY['expected_draft_version','expected_activation_version'] ELSE ARRAY['expected_activation_version','release_id'] END) IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2701'; END IF;\n        IF p_operation IN ('EDIT','PUBLISH') AND platform.human_context_decimal(p->'expected_draft_version',false) IS NOT TRUE\n          OR p_operation IN ('PUBLISH','ROLLBACK') AND platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE\n          OR p_operation='ROLLBACK' AND platform.human_context_uuid(p->'release_id') IS NOT TRUE\n          OR p_operation='EDIT' AND platform.configuration_bundle_shape(p->'bundle') IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2701'; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(ws::text||':'||p_business::text||'|CONFIGURATION_V1',2018));\n        IF platform.messaging_lock_owner(ws,actor) IS NOT TRUE THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2701'; END IF;\n        fingerprint:=sha256(convert_to(E'asm:m5:configuration:v1\\n'||jsonb_build_array(ws,actor,p_business,p_operation,p)::text,'UTF8'));\n        SELECT * INTO prior FROM platform.business_configuration_receipts WHERE workspace_id=ws AND business_id=p_business AND idempotency_key=p_key;\n        IF FOUND THEN\n          IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2701'; END IF;\n          RETURN jsonb_build_object('outcome','REPLAY','result',prior.result); END IF;\n        SELECT * INTO s FROM platform.business_configuration_state WHERE workspace_id=ws AND business_id=p_business FOR UPDATE;\n        moment:=clock_timestamp(); receipt:=uuidv7(); corr:=nullif(current_setting('asm.correlation_id',true),'')::uuid;\n        IF p_operation='EDIT' THEN\n          expected:=(p->>'expected_draft_version')::bigint;\n          IF expected<>coalesce(s.draft_version,0) THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2701'; END IF;\n          IF expected=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2701'; END IF;\n          IF s.workspace_id IS NULL THEN\n            INSERT INTO platform.business_configuration_state(workspace_id,business_id,draft_version,draft_body,updated_at)\n              VALUES(ws,p_business,1,p->'bundle',moment) RETURNING * INTO s;\n          ELSE UPDATE platform.business_configuration_state SET draft_version=draft_version+1,draft_body=p->'bundle',updated_at=moment\n            WHERE workspace_id=ws AND business_id=p_business RETURNING * INTO s; END IF;\n        ELSE\n          IF s.workspace_id IS NULL OR s.activation_version<>(p->>'expected_activation_version')::bigint\n            OR p_operation='PUBLISH' AND s.draft_version<>(p->>'expected_draft_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2701'; END IF;\n          IF s.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2701'; END IF;\n          IF p_operation='PUBLISH' THEN\n            IF EXISTS(SELECT 1 FROM platform.portfolio_release_builds WHERE workspace_id=ws AND business_id=p_business AND (release_id=s.active_release_id OR p_operation='ROLLBACK' AND release_id=(p->>'release_id')::uuid)) THEN RAISE EXCEPTION 'PORTFOLIO_BUILD_REQUIRED' USING ERRCODE='P2701'; END IF;\n            IF EXISTS(SELECT 1 FROM platform.knowledge_release_builds WHERE workspace_id=ws AND business_id=p_business AND release_id=s.active_release_id) THEN RAISE EXCEPTION 'KNOWLEDGE_BUILD_REQUIRED' USING ERRCODE='P2701'; END IF;\n            IF platform.configuration_validate(s.draft_body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2701'; END IF;\n            INSERT INTO platform.business_configuration_releases(workspace_id,business_id,source_draft_version,body,published_by,published_at)\n              VALUES(ws,p_business,s.draft_version,s.draft_body,actor,moment) RETURNING * INTO r;\n          ELSE\n            SELECT * INTO r FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=p_business AND id=(p->>'release_id')::uuid;\n            IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2701'; END IF;\n            IF EXISTS(SELECT 1 FROM platform.portfolio_release_builds WHERE workspace_id=ws AND business_id=p_business AND (release_id=s.active_release_id OR p_operation='ROLLBACK' AND release_id=(p->>'release_id')::uuid)) THEN RAISE EXCEPTION 'PORTFOLIO_BUILD_REQUIRED' USING ERRCODE='P2701'; END IF;\n            IF EXISTS(SELECT 1 FROM platform.knowledge_release_builds WHERE workspace_id=ws AND business_id=p_business AND release_id=r.id) AND platform.knowledge_release_eligible(ws,p_business,r.id) IS NOT TRUE THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            IF platform.configuration_validate(r.body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2701'; END IF;\n            SELECT body INTO current_body FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=p_business AND id=s.active_release_id;\n            FOR v IN SELECT value FROM jsonb_array_elements(r.body->'faqs') LOOP\n              IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_body->'faqs') c WHERE c=v) THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            END LOOP;\n            FOR v IN SELECT value FROM jsonb_array_elements(r.body->'services') LOOP\n              IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(current_body->'services') c WHERE c->'id'=v->'id'\n                AND jsonb_build_array(c->'name',c->'description',c->'intake_fields',c->'price'->'formula_note',c->'duration'->'rule_note')\n                  =jsonb_build_array(v->'name',v->'description',v->'intake_fields',v->'price'->'formula_note',v->'duration'->'rule_note')) THEN\n                RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2701'; END IF;\n            END LOOP;\n          END IF;\n          UPDATE platform.business_configuration_state SET active_release_id=r.id,activation_version=activation_version+1,updated_at=moment\n            WHERE workspace_id=ws AND business_id=p_business RETURNING * INTO s;\n        END IF;\n        result:=jsonb_build_object('workspace_id',ws,'business_id',p_business,'receipt_id',receipt,'operation',p_operation,\n          'draft_version',s.draft_version::text,'release_id',s.active_release_id,'activation_version',s.activation_version::text,\n          'recorded_at',to_char(moment AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'));\n        INSERT INTO platform.business_configuration_receipts(workspace_id,business_id,id,operation,idempotency_key,actor_user_account_id,correlation_id,request_fingerprint,result,recorded_at)\n          VALUES(ws,p_business,receipt,p_operation,p_key,actor,corr,fingerprint,result,moment);\n        RETURN jsonb_build_object('outcome','ACCEPTED','result',result);\n      END $$",
    "platform.knowledge_owner_command(uuid,text,text,jsonb)": "CREATE FUNCTION platform.knowledge_owner_command(business uuid,operation text,p_key text,p jsonb) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE ws uuid:=platform.knowledge_owner_lock(business); actor uuid:=nullif(current_setting('asm.actor_id',true),'')::uuid;\n  fields text[]; fingerprint bytea; prior platform.business_configuration_receipts%ROWTYPE;\n  s platform.knowledge_sources%ROWTYPE; r platform.knowledge_revisions%ROWTYPE; b platform.knowledge_builds%ROWTYPE;\n  config platform.business_configuration_state%ROWTYPE; release platform.business_configuration_releases%ROWTYPE;\n  canonical text; plan jsonb; chunk jsonb; source uuid; next_no bigint; result jsonb; receipt uuid:=uuidv7(); moment timestamptz:=clock_timestamp(); affected boolean;\nBEGIN\n  fields:=CASE operation\n    WHEN 'KNOWLEDGE_SAVE' THEN ARRAY['schema_version','source_id','expected_source_version','title','format','text','source_label','author_label','service_id','category','claim_key','effective_from','effective_until']\n    WHEN 'KNOWLEDGE_CONFIRM' THEN ARRAY['schema_version','source_id','expected_source_version','revision_id','canonical_sha256']\n    WHEN 'KNOWLEDGE_REVOKE' THEN ARRAY['schema_version','source_id','expected_source_version','expected_activation_version']\n    WHEN 'KNOWLEDGE_DELETE' THEN ARRAY['schema_version','source_id','expected_source_version','expected_activation_version']\n    WHEN 'KNOWLEDGE_BUILD_CREATE' THEN ARRAY['schema_version','expected_sources_hash','revision_ids']\n    WHEN 'KNOWLEDGE_PUBLISH' THEN ARRAY['schema_version','expected_draft_version','expected_activation_version','build_id','expected_build_version']\n    WHEN 'KNOWLEDGE_ROLLBACK' THEN ARRAY['schema_version','expected_activation_version','release_id'] END;\n  IF fields IS NULL OR platform.material_object(p,fields) IS NOT TRUE OR p->'schema_version' IS DISTINCT FROM '1'::jsonb OR p->>'schema_version'<>'1'\n    OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$' OR octet_length(convert_to(p::text,'UTF8'))>8192 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  fingerprint:=sha256(convert_to(E'asm:m5:knowledge:v1\\n'||jsonb_build_array(ws,actor,business,operation,p)::text,'UTF8'));\n  SELECT * INTO prior FROM platform.business_configuration_receipts WHERE workspace_id=ws AND business_id=business AND idempotency_key=p_key;\n  IF FOUND THEN\n    IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2801'; END IF;\n    RETURN jsonb_build_object('schema_version',1,'outcome','REPLAY','result',prior.result); END IF;\n  SELECT * INTO config FROM platform.business_configuration_state WHERE workspace_id=ws AND business_id=business FOR UPDATE;\n  IF operation IN ('KNOWLEDGE_SAVE','KNOWLEDGE_CONFIRM','KNOWLEDGE_REVOKE','KNOWLEDGE_DELETE') THEN\n    IF platform.human_context_decimal(p->'expected_source_version',false) IS NOT TRUE OR NOT (p->'source_id'='null'::jsonb OR platform.human_context_uuid(p->'source_id')) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    source:=(p->>'source_id')::uuid;\n    IF source IS NOT NULL THEN\n      SELECT * INTO s FROM platform.knowledge_sources WHERE workspace_id=ws AND business_id=business AND id=source FOR UPDATE;\n      IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2801'; END IF;\n      IF s.state='DELETED' THEN RAISE EXCEPTION 'SOURCE_DELETED' USING ERRCODE='P2801'; END IF;\n    ELSIF operation<>'KNOWLEDGE_SAVE' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF coalesce(s.version,0)<>(p->>'expected_source_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF s.version=9223372036854775807 OR s.revocation_epoch=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n  END IF;\n  IF operation='KNOWLEDGE_SAVE' THEN\n    canonical:=platform.knowledge_normalize(p->>'text');\n    IF jsonb_typeof(p->'text') IS DISTINCT FROM 'string' OR octet_length(convert_to(canonical,'UTF8')) NOT BETWEEN 1 AND 2048 OR NOT platform.human_context_text_valid(canonical)\n      OR NOT platform.configuration_text_valid(p->'title',120,true) OR p->>'format' NOT IN ('TEXT','MARKDOWN') OR NOT platform.configuration_text_valid(p->'source_label',120,true)\n      OR NOT (p->'author_label'='null'::jsonb OR platform.configuration_text_valid(p->'author_label',80,false)) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    FOR canonical IN SELECT key FROM jsonb_each(p) WHERE key IN ('service_id','category','claim_key') LOOP\n      IF NOT (p->canonical='null'::jsonb OR jsonb_typeof(p->canonical)='string' AND p->>canonical ~ '^[a-z][a-z0-9_-]{0,39}$') THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    END LOOP;\n    FOR canonical IN SELECT key FROM jsonb_each(p) WHERE key IN ('effective_from','effective_until') LOOP\n      IF p->canonical<>'null'::jsonb AND (jsonb_typeof(p->canonical)<>'string' OR p->>canonical !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}[.][0-9]{6}Z$'\n        OR NOT isfinite((p->>canonical)::timestamptz) OR to_char((p->>canonical)::timestamptz AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"')<>p->>canonical) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    END LOOP;\n    IF p->>'effective_from' IS NOT NULL AND p->>'effective_until' IS NOT NULL AND (p->>'effective_until')::timestamptz<=(p->>'effective_from')::timestamptz THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    canonical:=platform.knowledge_normalize(p->>'text');\n    IF s.id IS NULL THEN\n      IF (SELECT count(*) FROM platform.knowledge_sources WHERE workspace_id=ws AND business_id=business AND state<>'DELETED')>=8 THEN RAISE EXCEPTION 'SOURCE_LIMIT' USING ERRCODE='P2801'; END IF;\n      INSERT INTO platform.knowledge_sources(workspace_id,business_id,state) VALUES(ws,business,'DRAFT') RETURNING * INTO s;\n      next_no:=1;\n    ELSE\n      SELECT revision_no+1 INTO next_no FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND id=s.head_revision_id;\n      IF next_no IS NULL THEN RAISE EXCEPTION 'SOURCE_DELETED' USING ERRCODE='P2801'; END IF;\n    END IF;\n    INSERT INTO platform.knowledge_revisions(workspace_id,business_id,source_id,revision_no,title,format,canonical_text,canonical_sha256,source_label,author_label,service_id,category,claim_key,effective_from,effective_until,created_by)\n      VALUES(ws,business,s.id,next_no,p->>'title',p->>'format',canonical,encode(sha256(convert_to(canonical,'UTF8')),'hex'),p->>'source_label',p->>'author_label',p->>'service_id',p->>'category',p->>'claim_key',(p->>'effective_from')::timestamptz,(p->>'effective_until')::timestamptz,actor) RETURNING * INTO r;\n    plan:=platform.knowledge_plan(canonical);\n    FOR chunk IN SELECT value FROM jsonb_array_elements(plan->'chunks') LOOP\n      INSERT INTO platform.knowledge_chunks(workspace_id,business_id,revision_id,ordinal,text,sha256) VALUES(ws,business,r.id,(chunk->>'ordinal')::integer,chunk->>'text',chunk->>'sha256');\n    END LOOP;\n    UPDATE platform.knowledge_sources SET head_revision_id=r.id,state='DRAFT',version=CASE WHEN source IS NULL THEN version ELSE version+1 END WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n  ELSIF operation='KNOWLEDGE_CONFIRM' THEN\n    IF platform.human_context_uuid(p->'revision_id') IS NOT TRUE OR p->>'canonical_sha256' !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    SELECT * INTO r FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND id=s.head_revision_id;\n    IF r.id::text IS DISTINCT FROM p->>'revision_id' OR r.canonical_sha256 IS DISTINCT FROM p->>'canonical_sha256' THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF platform.knowledge_plan(r.canonical_text)->'issues'<>'[]'::jsonb THEN RAISE EXCEPTION 'CHUNK_LIMIT' USING ERRCODE='P2801'; END IF;\n    IF r.confirmed THEN\n      IF r.confirmed_epoch<>s.revocation_epoch THEN RAISE EXCEPTION 'SOURCE_REVOKED' USING ERRCODE='P2801'; END IF;\n    ELSE UPDATE platform.knowledge_revisions SET confirmed=true,confirmed_by=actor,confirmed_at=moment,confirmed_epoch=s.revocation_epoch WHERE workspace_id=ws AND business_id=business AND id=r.id RETURNING * INTO r;\n      UPDATE platform.knowledge_sources SET confirmed_revision_id=r.id,state='CONFIRMED',version=version+1 WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n    END IF;\n  ELSIF operation IN ('KNOWLEDGE_REVOKE','KNOWLEDGE_DELETE') THEN\n    IF platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF coalesce(config.activation_version,0)<>(p->>'expected_activation_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    affected:=EXISTS(SELECT 1 FROM platform.knowledge_release_builds l JOIN platform.knowledge_builds kb ON (kb.workspace_id,kb.business_id,kb.id)=(l.workspace_id,l.business_id,l.build_id),jsonb_array_elements(kb.manifest) m\n      WHERE l.workspace_id=ws AND l.business_id=business AND l.release_id=config.active_release_id AND m->>'source_id'=s.id::text);\n    IF affected AND config.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n    DELETE FROM platform.knowledge_build_chunks p USING platform.knowledge_chunks c,platform.knowledge_revisions kr WHERE (p.workspace_id,p.business_id,p.chunk_id)=(c.workspace_id,c.business_id,c.id)\n      AND (kr.workspace_id,kr.business_id,kr.id)=(c.workspace_id,c.business_id,c.revision_id) AND kr.workspace_id=ws AND kr.business_id=business AND kr.source_id=s.id;\n    UPDATE platform.knowledge_sources SET state=CASE WHEN operation='KNOWLEDGE_DELETE' THEN 'DELETED' ELSE 'REVOKED' END,version=version+1,revocation_epoch=revocation_epoch+1,revoked_at=moment,\n      deleted_at=CASE WHEN operation='KNOWLEDGE_DELETE' THEN moment END,head_revision_id=CASE WHEN operation='KNOWLEDGE_DELETE' THEN NULL ELSE head_revision_id END,\n      confirmed_revision_id=CASE WHEN operation='KNOWLEDGE_DELETE' THEN NULL ELSE confirmed_revision_id END WHERE workspace_id=ws AND business_id=business AND id=s.id RETURNING * INTO s;\n    IF operation='KNOWLEDGE_DELETE' THEN\n      DELETE FROM platform.knowledge_chunks c USING platform.knowledge_revisions kr WHERE (kr.workspace_id,kr.business_id,kr.id)=(c.workspace_id,c.business_id,c.revision_id) AND kr.workspace_id=ws AND kr.business_id=business AND kr.source_id=s.id;\n      DELETE FROM platform.knowledge_revisions WHERE workspace_id=ws AND business_id=business AND source_id=s.id;\n    END IF;\n    IF affected THEN UPDATE platform.business_configuration_state SET activation_version=activation_version+1,updated_at=moment WHERE workspace_id=ws AND business_id=business RETURNING * INTO config; END IF;\n  ELSIF operation='KNOWLEDGE_BUILD_CREATE' THEN\n    b:=platform.knowledge_build_create(ws,business,actor,p);\n  ELSIF operation IN ('KNOWLEDGE_PUBLISH','KNOWLEDGE_ROLLBACK') THEN\n    IF platform.human_context_decimal(p->'expected_activation_version',false) IS NOT TRUE OR config.workspace_id IS NULL OR config.activation_version<>(p->>'expected_activation_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n    IF config.activation_version=9223372036854775807 THEN RAISE EXCEPTION 'VERSION_EXHAUSTED' USING ERRCODE='P2801'; END IF;\n    IF operation='KNOWLEDGE_PUBLISH' THEN\n      IF platform.human_context_uuid(p->'build_id') IS NOT TRUE OR platform.human_context_decimal(p->'expected_build_version',true) IS NOT TRUE\n        OR platform.human_context_decimal(p->'expected_draft_version',true) IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n      SELECT * INTO b FROM platform.knowledge_builds WHERE workspace_id=ws AND business_id=business AND id=(p->>'build_id')::uuid FOR UPDATE;\n      IF b.id IS NULL OR b.version<>(p->>'expected_build_version')::bigint OR config.draft_version<>(p->>'expected_draft_version')::bigint THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2801'; END IF;\n      IF EXISTS(SELECT 1 FROM platform.portfolio_release_builds WHERE workspace_id=ws AND business_id=business AND (release_id=config.active_release_id OR operation='KNOWLEDGE_ROLLBACK' AND release_id=(p->>'release_id')::uuid)) THEN RAISE EXCEPTION 'PORTFOLIO_BUILD_REQUIRED' USING ERRCODE='P2801'; END IF;\n      IF platform.knowledge_build_valid(ws,business,b.id,true) IS NOT TRUE THEN RAISE EXCEPTION 'BUILD_NOT_READY' USING ERRCODE='P2801'; END IF;\n      IF platform.configuration_validate(config.draft_body)->'valid' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'VALIDATION_FAILED' USING ERRCODE='P2801'; END IF;\n      IF EXISTS(SELECT 1 FROM jsonb_array_elements(b.manifest) m JOIN platform.knowledge_revisions kr ON (kr.workspace_id,kr.business_id,kr.id)=(ws,business,(m->>'revision_id')::uuid)\n        WHERE kr.service_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(config.draft_body->'services') service WHERE service->>'id'=kr.service_id AND service->'active'='true'::jsonb)) THEN RAISE EXCEPTION 'INVALID_REFERENCE' USING ERRCODE='P2801'; END IF;\n      INSERT INTO platform.business_configuration_releases(workspace_id,business_id,source_draft_version,body,published_by,published_at) VALUES(ws,business,config.draft_version,config.draft_body,actor,moment) RETURNING * INTO release;\n      INSERT INTO platform.knowledge_release_builds(workspace_id,business_id,release_id,build_id) VALUES(ws,business,release.id,b.id);\n    ELSE\n      IF platform.human_context_uuid(p->'release_id') IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n      SELECT * INTO release FROM platform.business_configuration_releases WHERE workspace_id=ws AND business_id=business AND id=(p->>'release_id')::uuid;\n      IF release.id IS NULL THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2801'; END IF;\n      IF EXISTS(SELECT 1 FROM platform.portfolio_release_builds WHERE workspace_id=ws AND business_id=business AND (release_id=config.active_release_id OR operation='KNOWLEDGE_ROLLBACK' AND release_id=(p->>'release_id')::uuid)) THEN RAISE EXCEPTION 'PORTFOLIO_BUILD_REQUIRED' USING ERRCODE='P2801'; END IF;\n      IF platform.knowledge_release_eligible(ws,business,release.id) IS NOT TRUE THEN RAISE EXCEPTION 'ROLLBACK_NOT_ALLOWED' USING ERRCODE='P2801'; END IF;\n      SELECT kb.* INTO b FROM platform.knowledge_release_builds l JOIN platform.knowledge_builds kb ON (kb.workspace_id,kb.business_id,kb.id)=(l.workspace_id,l.business_id,l.build_id) WHERE l.workspace_id=ws AND l.business_id=business AND l.release_id=release.id;\n    END IF;\n    UPDATE platform.business_configuration_state SET active_release_id=release.id,activation_version=activation_version+1,updated_at=moment WHERE workspace_id=ws AND business_id=business RETURNING * INTO config;\n  END IF;\n  result:=jsonb_build_object('workspace_id',ws,'business_id',business,'receipt_id',receipt,'operation',operation,\n    'source_id',s.id,'source_version',s.version::text,'revision_id',r.id,'build_id',b.id,'build_version',b.version::text,\n    'release_id',config.active_release_id,'activation_version',coalesce(config.activation_version,0)::text,\n    'recorded_at',to_char(moment AT TIME ZONE 'UTC','YYYY-MM-DD\"T\"HH24:MI:SS.US\"Z\"'),'request_hash',encode(fingerprint,'hex'));\n  INSERT INTO platform.business_configuration_receipts(workspace_id,business_id,id,operation,idempotency_key,actor_user_account_id,correlation_id,request_fingerprint,result,recorded_at)\n    VALUES(ws,business,receipt,operation,p_key,actor,nullif(current_setting('asm.correlation_id',true),'')::uuid,fingerprint,result,moment);\n  RETURN jsonb_build_object('schema_version',1,'outcome','ACCEPTED','result',result);\nEXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format OR datetime_field_overflow THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801';\nEND $$",
    "platform.knowledge_embedding_complete(uuid,uuid,jsonb)": "CREATE FUNCTION platform.knowledge_embedding_complete(p_call uuid,p_ticket uuid,p jsonb) RETURNS jsonb\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE ec platform.knowledge_embedding_calls%ROWTYPE; record jsonb; completion_state text; validation text; vectors_hash text; next_state text; valid_usage boolean; detail_name text; detail jsonb; detail_item record; raw_cost jsonb; reported_cost numeric;\nBEGIN\n  IF current_database() NOT IN ('asm_local','asm_test') OR p_ticket IS NULL THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2801'; END IF;\n  SELECT * INTO ec FROM platform.knowledge_embedding_calls WHERE id=p_call;\n  IF ec.id IS NULL OR ec.ticket_hash IS DISTINCT FROM sha256(convert_to(p_ticket::text,'UTF8')) THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2801'; END IF;\n  IF ec.portfolio_session_id IS NOT NULL THEN\n    PERFORM pg_advisory_xact_lock(hashtextextended(ec.workspace_id::text||':'||ec.business_id::text||'|CONFIGURATION_V1',2018));\n    PERFORM 1 FROM platform.portfolio_ai_sessions WHERE id=ec.portfolio_session_id FOR UPDATE;\n    IF ec.kind='PORTFOLIO_INDEX' THEN PERFORM 1 FROM platform.portfolio_builds WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.portfolio_build_id FOR UPDATE; END IF;\n  END IF;\n  IF ec.kind='INDEX_BATCH' THEN\n    PERFORM pg_advisory_xact_lock(hashtextextended(ec.workspace_id::text||':'||ec.business_id::text||'|CONFIGURATION_V1',2018));\n    PERFORM 1 FROM platform.knowledge_builds WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.build_id FOR UPDATE;\n  END IF;\n  SELECT * INTO STRICT ec FROM platform.knowledge_embedding_calls WHERE id=p_call FOR UPDATE;\n  IF platform.material_object(p,ARRAY['kind','vectors','usage','cost','identity','request_id','error_code']) IS NOT TRUE OR octet_length(p::text)>262144\n    OR p->>'kind' NOT IN ('SUCCESS','ERROR','UNKNOWN') OR jsonb_typeof(p->'usage') IS DISTINCT FROM 'object' OR octet_length((p->'usage')::text)>2048\n    OR platform.material_object(p->'cost',ARRAY['status','amount','currency']) IS NOT TRUE OR p->'cost'->>'status' NOT IN ('CONFIRMED','UNKNOWN') OR p->'cost'->>'currency'<>'RUB'\n    OR platform.material_object(p->'identity',ARRAY['status','source','provider','model']) IS NOT TRUE OR p->'identity'->>'status' NOT IN ('CONFIRMED','UNVERIFIED')\n    OR p->'identity'->>'source' NOT IN ('BODY','HISTORY','NONE') OR NOT (p->'identity'->'provider'='null'::jsonb OR p->'identity'->>'provider'='OpenAI')\n    OR NOT (p->'identity'->'model'='null'::jsonb OR jsonb_typeof(p->'identity'->'model')='string' AND char_length(p->'identity'->>'model')<=128)\n    OR NOT (p->'request_id'='null'::jsonb OR jsonb_typeof(p->'request_id')='string' AND p->>'request_id' ~ '^[A-Za-z0-9._:-]{1,128}$')\n    OR NOT (p->'error_code'='null'::jsonb OR p->>'error_code' IN ('TRANSPORT','TIMEOUT','INVALID_RESPONSE','PROFILE_MISMATCH','IDENTITY_UNVERIFIED','USAGE_INVALID','COST_UNKNOWN','COST_LIMIT','DISABLED','CANCELLED','SOURCE_STALE')) THEN\n    RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  IF p->'cost'->>'status'='UNKNOWN' THEN\n    IF p->'cost'->'amount'<>'null'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  ELSE\n    IF jsonb_typeof(p->'cost'->'amount') IS DISTINCT FROM 'string' OR p->'cost'->>'amount' !~ '^(0|[1-9][0-9]{0,6})([.][0-9]{1,9})?$' THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n    IF (p->'cost'->>'amount')::numeric>1000000 THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  END IF;\n  completion_state:=CASE WHEN NOT (p->'usage' ? 'completion_tokens') THEN 'NOT_APPLICABLE'\n    WHEN jsonb_typeof(p->'usage'->'completion_tokens')='number' AND p->'usage'->>'completion_tokens'='0' THEN 'ZERO' ELSE 'INVALID' END;\n  valid_usage:=coalesce(NOT EXISTS(SELECT 1 FROM jsonb_object_keys(p->'usage') AS u(name) WHERE name NOT IN\n      ('prompt_tokens','total_tokens','completion_tokens','cost','cost_rub','prompt_tokens_details','completion_tokens_details','server_tool_use'))\n    AND jsonb_typeof(p->'usage'->'prompt_tokens')='number' AND p->'usage'->>'prompt_tokens' ~ '^[1-9][0-9]{0,6}$'\n    AND jsonb_typeof(p->'usage'->'total_tokens')='number' AND p->'usage'->>'total_tokens' ~ '^[1-9][0-9]{0,6}$'\n    AND p->'usage'->'prompt_tokens'=p->'usage'->'total_tokens'\n    AND CASE WHEN jsonb_typeof(p->'usage'->'total_tokens')='number' AND p->'usage'->>'total_tokens' ~ '^[1-9][0-9]{0,6}$' THEN (p->'usage'->>'total_tokens')::numeric<=ec.token_ceiling ELSE false END\n    AND completion_state<>'INVALID',false);\n  FOR detail_name IN SELECT unnest(ARRAY['prompt_tokens_details','completion_tokens_details','server_tool_use']) LOOP\n    detail:=p->'usage'->detail_name;\n    IF detail IS NULL OR detail='null'::jsonb THEN CONTINUE; END IF;\n    IF jsonb_typeof(detail)<>'object' THEN valid_usage:=false; CONTINUE; END IF;\n    IF (SELECT count(*) FROM jsonb_object_keys(detail))>8 THEN valid_usage:=false; CONTINUE; END IF;\n    FOR detail_item IN SELECT key,value FROM jsonb_each(detail) LOOP\n      IF detail_item.key !~ '^[a-z][a-z0-9_]{0,63}$' OR jsonb_typeof(detail_item.value)<>'number'\n        OR detail_item.value#>>'{}' !~ '^(0|[1-9][0-9]{0,6})$' THEN valid_usage:=false;\n      ELSIF (detail_item.value#>>'{}')::numeric>8192\n        OR ((detail_name='server_tool_use' OR detail_item.key ~ '(reasoning|audio|tool)') AND detail_item.value<>'0'::jsonb) THEN valid_usage:=false; END IF;\n    END LOOP;\n  END LOOP;\n  FOR detail_name IN SELECT unnest(ARRAY['cost','cost_rub']) LOOP\n    raw_cost:=p->'usage'->detail_name;\n    IF raw_cost IS NULL THEN CONTINUE; END IF;\n    IF jsonb_typeof(raw_cost) NOT IN ('string','number') OR raw_cost#>>'{}' !~ '^(0|[1-9][0-9]{0,6})([.][0-9]{1,18})?([eE][+-]?[0-9]{1,3})?$' THEN valid_usage:=false; CONTINUE; END IF;\n    IF (raw_cost#>>'{}')::numeric>1000000 OR (reported_cost IS NOT NULL AND reported_cost<>(raw_cost#>>'{}')::numeric) THEN valid_usage:=false; END IF;\n    reported_cost:=(raw_cost#>>'{}')::numeric;\n  END LOOP;\n  IF reported_cost IS NOT NULL AND p->'cost'->>'status'='CONFIRMED' AND reported_cost<>(p->'cost'->>'amount')::numeric THEN valid_usage:=false; END IF;\n  IF p->>'kind'='SUCCESS' THEN\n    IF platform.knowledge_vectors_valid(p->'vectors',ec.input_count) IS NOT TRUE THEN validation:='INVALID_VECTOR';\n    ELSE vectors_hash:=encode(sha256(convert_to((p->'vectors')::text,'UTF8')),'hex'); END IF;\n    IF NOT valid_usage THEN validation:='USAGE_INVALID'; END IF;\n    IF p->'identity'->>'status'<>'CONFIRMED' OR p->'identity'->>'source' NOT IN ('BODY','HISTORY')\n      OR p->'identity'->>'provider' IS DISTINCT FROM 'OpenAI' OR p->'identity'->>'model' IS DISTINCT FROM 'openai/text-embedding-3-small'\n      OR p->'identity'->>'source'='HISTORY' AND p->'request_id'='null'::jsonb THEN validation:='IDENTITY_UNVERIFIED'; END IF;\n    IF p->'cost'->>'status'<>'CONFIRMED' THEN validation:='COST_UNKNOWN'; END IF;\n    IF p->'cost'->>'status'='CONFIRMED' AND (p->'cost'->>'amount')::numeric>ec.reserved_cost THEN validation:='COST_LIMIT'; END IF;\n  ELSIF p->'vectors'<>'null'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2801'; END IF;\n  record:=(p-'vectors')||jsonb_build_object('completion_tokens_state',completion_state,'validation_error',validation);\n  next_state:=CASE WHEN p->>'kind'='SUCCESS' AND validation IS NOT NULL THEN 'ERROR' ELSE p->>'kind' END;\n  IF ec.state<>'RESERVED' THEN\n    IF ec.outcome IS DISTINCT FROM record OR ec.vectors_sha256 IS DISTINCT FROM vectors_hash THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2801'; END IF;\n  ELSE\n    UPDATE platform.knowledge_embedding_calls SET state=next_state,outcome=record,completed_at=clock_timestamp(),vectors_sha256=vectors_hash WHERE id=ec.id RETURNING * INTO ec;\n    IF ec.kind='PORTFOLIO_INDEX' AND ec.state IN ('ERROR','UNKNOWN') THEN\n      UPDATE platform.portfolio_builds SET state=ec.state,error_code=CASE WHEN ec.state='UNKNOWN' THEN 'EMBEDDING_UNKNOWN' ELSE 'EMBEDDING_ERROR' END,version=version+1 WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.portfolio_build_id;\n    END IF;\n    IF ec.kind='INDEX_BATCH' AND ec.state IN ('ERROR','UNKNOWN') THEN\n      UPDATE platform.knowledge_builds SET state=CASE WHEN ec.state='UNKNOWN' THEN 'UNKNOWN' ELSE 'ERROR' END,\n        error_code=CASE WHEN ec.state='UNKNOWN' THEN 'EMBEDDING_UNKNOWN' ELSE 'EMBEDDING_ERROR' END,version=version+1 WHERE workspace_id=ec.workspace_id AND business_id=ec.business_id AND id=ec.build_id;\n    END IF;\n  END IF;\n  RETURN jsonb_build_object('call_id',ec.id,'state',ec.state,'vectors_sha256',ec.vectors_sha256,'validation_error',ec.outcome->'validation_error',\n    'usage',ec.outcome->'usage','cost',ec.outcome->'cost','identity',ec.outcome->'identity','completion_tokens_state',ec.outcome->'completion_tokens_state');\nEND $$",
    "platform.ai_runtime_config_valid(jsonb)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_config_valid(p jsonb) RETURNS boolean\nLANGUAGE sql IMMUTABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nSELECT (p->>'prompt_revision' IN ('conversation_v4','conversation_v5') AND (p->>'prompt_revision'<>'conversation_v5' OR p->'limits'->>'currency'='RUB') AND platform.ai_synthetic_config_valid(jsonb_set(p,'{prompt_revision}','\"conversation_v2\"'::jsonb))) OR platform.ai_synthetic_config_valid(p) OR platform.ai_provider_config_valid(p) OR\n  (p->>'prompt_revision'='conversation_v3' AND\n    platform.ai_synthetic_config_valid(jsonb_set(p,'{prompt_revision}','\"conversation_v2\"'::jsonb))) $$",
    "platform.ai_runtime_command(uuid,uuid,text,jsonb)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_command(p_job uuid,p_claim uuid,p_op text,p jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE j platform.messaging_jobs%ROWTYPE; r platform.ai_runs%ROWTYPE; previous platform.ai_provider_calls%ROWTYPE;\n        fresh jsonb; knowledge jsonb; search jsonb; portfolio jsonb; media jsonb; session uuid; auxiliary numeric:=0; b jsonb; cfg jsonb; lim jsonb; expiry timestamptz; next_job uuid; n integer; tokens integer; cost numeric;\n      BEGIN\n        PERFORM platform.turn_require_isolation();\n        j:=platform.messaging_guard(p_job,p_claim);\n        IF current_database() NOT IN ('asm_local','asm_test') OR jsonb_typeof(p) IS DISTINCT FROM 'object' OR octet_length(p::text)>32768 THEN\n          RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF p_op='ENQUEUE' THEN\n          IF j.kind<>'PROCESS_TURN' OR j.step<>'TEST_CONSUME' OR p<>'{}'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          PERFORM platform.ai_runtime_current(j,NULL);\n          INSERT INTO platform.messaging_jobs(workspace_id,connection_id,kind,turn_id,turn_revision,step,correlation_id)\n            VALUES(j.workspace_id,j.connection_id,'PROCESS_TURN',j.turn_id,j.turn_revision,'AI_GENERATE',j.correlation_id)\n            ON CONFLICT(workspace_id,turn_id,turn_revision,step) DO NOTHING;\n          SELECT id INTO STRICT next_job FROM platform.messaging_jobs WHERE workspace_id=j.workspace_id AND turn_id=j.turn_id AND turn_revision=j.turn_revision AND step='AI_GENERATE';\n          RETURN jsonb_build_object('job_id',next_job);\n        END IF;\n        IF j.kind<>'PROCESS_TURN' OR j.step<>'AI_GENERATE' THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        SELECT * INTO r FROM platform.ai_runs WHERE workspace_id=j.workspace_id AND job_id=j.id FOR UPDATE;\n        IF p_op='PREPARE' THEN\n          cfg:=p->'config';\n          IF NOT platform.material_object(p,ARRAY['config','deadline']||CASE WHEN cfg->>'prompt_revision'='conversation_v5' THEN ARRAY['portfolio_session_id'] ELSE ARRAY[]::text[] END) OR jsonb_typeof(p->'deadline') IS DISTINCT FROM 'string'\n            OR platform.ai_runtime_config_valid(cfg) IS NOT TRUE OR cfg->>'prompt_revision' NOT IN ('conversation_v3','conversation_v4','conversation_v5') THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF r.id IS NOT NULL AND r.config IS DISTINCT FROM cfg THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n          BEGIN fresh:=platform.ai_runtime_current(j,r.snapshot);\n          EXCEPTION WHEN SQLSTATE 'P2001' THEN\n            IF r.id IS NOT NULL AND SQLERRM='AI_STALE' THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n            RAISE;\n          END;\n          IF cfg->'route'->>'execution'='PROVIDER' THEN\n            PERFORM platform.ai_provider_guard((SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id),j,cfg);\n          ELSIF (SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id) IS NOT NULL THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          IF r.id IS NOT NULL THEN\n            IF fresh->'binding' IS DISTINCT FROM r.binding OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n            RETURN platform.ai_runtime_view(r);\n          END IF;\n          expiry:=least((p->>'deadline')::timestamptz,clock_timestamp()+(cfg->'limits'->>'duration_seconds')::numeric*interval '1 second');\n          IF NOT isfinite(expiry) OR expiry<=clock_timestamp() THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          b:=fresh->'binding';\n          knowledge:=platform.ai_knowledge_snapshot(j.workspace_id,(b->>'business_id')::uuid);\n          search:=CASE WHEN cfg->>'prompt_revision' IN ('conversation_v4','conversation_v5') THEN platform.knowledge_availability(j.workspace_id,(b->>'business_id')::uuid,(knowledge->'knowledge_pin'->>'release_id')::uuid,(knowledge->'knowledge_pin'->>'activation_version')::bigint) END;\n          IF cfg->>'prompt_revision'='conversation_v5' THEN\n            IF platform.human_context_uuid(p->'portfolio_session_id') IS NOT TRUE THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n            session:=(p->>'portfolio_session_id')::uuid;\n            PERFORM platform.portfolio_session_lock(j.workspace_id,(b->>'business_id')::uuid,session,0);\n            IF NOT EXISTS(SELECT 1 FROM platform.portfolio_ai_sessions WHERE id=session AND conversation_id=(b->>'conversation_id')::uuid AND client_id=(b->>'client_id')::uuid) THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n            portfolio:=platform.portfolio_availability(j.workspace_id,(b->>'business_id')::uuid,(knowledge->'knowledge_pin'->>'release_id')::uuid,(knowledge->'knowledge_pin'->>'activation_version')::bigint);\n            media:=platform.portfolio_media_pin(j.workspace_id,(b->>'business_id')::uuid,(b->>'client_id')::uuid,(b->>'conversation_id')::uuid,true);\n            auxiliary:=platform.portfolio_auxiliary_cost(j.workspace_id,(b->>'business_id')::uuid,(b->>'client_id')::uuid,(b->>'conversation_id')::uuid,media,NULL);\n            IF auxiliary>(cfg->'limits'->>'cost_budget')::numeric THEN RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          END IF;\n          INSERT INTO platform.ai_runs(workspace_id,job_id,connection_id,conversation_id,client_id,business_id,turn_id,turn_revision,\n            resume_receipt_id,control_generation,binding,snapshot,snapshot_digest,storage_fingerprint,config,config_fingerprint,deadline,knowledge_pin,active_projection,search_pin,portfolio_pin,media_pin,portfolio_session_id,cost_reserved)\n          VALUES(j.workspace_id,j.id,j.connection_id,(b->>'conversation_id')::uuid,(b->>'client_id')::uuid,(b->>'business_id')::uuid,j.turn_id,j.turn_revision,\n            (b->>'resume_receipt_id')::uuid,(b->>'control_generation')::bigint,b,fresh->'snapshot',b->>'snapshot_digest',encode(sha256(convert_to((fresh->'snapshot')::text,'UTF8')),'hex'),cfg,encode(sha256(convert_to(cfg::text,'UTF8')),'hex'),expiry,knowledge->'knowledge_pin',knowledge->'active_projection',search,portfolio,media,session,auxiliary) RETURNING * INTO r;\n          RETURN platform.ai_runtime_view(r);\n        END IF;\n        IF r.id IS NULL OR p->>'run_id' IS DISTINCT FROM r.id::text THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF p_op='COMPLETE' THEN\n          IF NOT platform.material_object(p,ARRAY['run_id','sequence','completion']) OR platform.ai_runtime_completion_valid(p->'completion') IS NOT TRUE THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          SELECT * INTO previous FROM platform.ai_provider_calls WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=(p->>'sequence')::int FOR UPDATE;\n          IF previous.claim_hash IS DISTINCT FROM sha256(convert_to(p_claim::text,'UTF8')) OR previous.attempt_count IS DISTINCT FROM j.attempt_count THEN\n            RAISE EXCEPTION 'STALE_CLAIM' USING ERRCODE='P2001'; END IF;\n          IF previous.completed_at IS NOT NULL THEN\n            IF previous.completion IS DISTINCT FROM p->'completion' THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n          ELSE\n            UPDATE platform.ai_provider_calls SET completion=p->'completion',completed_at=clock_timestamp()\n              WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=previous.sequence;\n          END IF;\n          RETURN jsonb_build_object('recorded',true);\n        END IF;\n        fresh:=platform.ai_runtime_current(j,r.snapshot);\n        IF fresh->'binding' IS DISTINCT FROM r.binding OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        IF r.deadline<=clock_timestamp() OR r.result IS NOT NULL THEN RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n        IF r.config->'route'->>'execution'='PROVIDER' THEN\n          PERFORM platform.ai_provider_guard((SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id),j,r.config);\n        END IF;\n        IF r.config->>'prompt_revision' IN ('conversation_v4','conversation_v5') AND r.search_refs IS NULL THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n        lim:=r.config->'limits';\n        SELECT * INTO previous FROM platform.ai_provider_calls WHERE workspace_id=j.workspace_id AND run_id=r.id AND sequence=r.calls_used;\n        IF p_op IN ('AUTHORIZE','READ') THEN\n          IF p->'binding' IS DISTINCT FROM r.binding OR p->'knowledge_pin' IS DISTINCT FROM r.knowledge_pin OR (r.config->>'prompt_revision' IN ('conversation_v4','conversation_v5') AND p->'search_pin' IS DISTINCT FROM r.search_pin) OR (r.config->>'prompt_revision'='conversation_v5' AND (p->'portfolio_pin' IS DISTINCT FROM r.portfolio_pin OR p->'media_pin' IS DISTINCT FROM r.media_pin)) THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n          IF (p_op='AUTHORIZE' AND (NOT platform.material_object(p,ARRAY['run_id','binding','knowledge_pin','boundary']||CASE WHEN r.config->>'prompt_revision' IN ('conversation_v4','conversation_v5') THEN ARRAY['search_pin']||CASE WHEN r.config->>'prompt_revision'='conversation_v5' THEN ARRAY['portfolio_pin','media_pin'] ELSE ARRAY[]::text[] END ELSE ARRAY[]::text[] END) OR p->>'boundary' NOT IN ('MODEL','READ','FOLLOWUP','CANDIDATE')))\n            OR (p_op='READ' AND NOT platform.material_object(p,ARRAY['run_id','binding','knowledge_pin']||CASE WHEN r.config->>'prompt_revision' IN ('conversation_v4','conversation_v5') THEN ARRAY['search_pin']||CASE WHEN r.config->>'prompt_revision'='conversation_v5' THEN ARRAY['portfolio_pin','media_pin'] ELSE ARRAY[]::text[] END ELSE ARRAY[]::text[] END)) THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF p->>'boundary'='MODEL' AND r.calls_used<>0 THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          IF p_op='READ' OR p->>'boundary' IN ('READ','FOLLOWUP') THEN\n            IF r.calls_used<>1 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'TOOLS'\n              OR (lim->>'read_executions')::int<1 THEN RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n            IF (p_op='READ' OR p->>'boundary'='READ') AND r.reads_used<>0 OR p->>'boundary'='FOLLOWUP' AND r.reads_used<>1 THEN\n              RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          END IF;\n          IF p->>'boundary'='CANDIDATE' AND (r.calls_used=0 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'OUTPUT') THEN\n            RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          IF p_op='READ' THEN\n            UPDATE platform.ai_runs SET reads_used=1,read_audit=jsonb_build_object('outcome','READ','context_version',r.binding->'context_version',\n              'turn_revision',r.turn_revision,'native',r.binding->'native','knowledge_pin',r.knowledge_pin,'at',clock_timestamp())||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin_sha256',encode(sha256(convert_to(r.search_pin::text,'UTF8')),'hex')) ELSE '{}'::jsonb END WHERE workspace_id=j.workspace_id AND id=r.id;\n            RETURN jsonb_build_object('binding',r.binding,'snapshot',r.snapshot,\n              'knowledge_pin',r.knowledge_pin,'active_projection',r.active_projection)\n              ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs,'search_projection',platform.knowledge_projection(r)) ELSE '{}'::jsonb END||platform.portfolio_runtime_data(r)||CASE WHEN r.config->>'prompt_revision'='conversation_v5' THEN jsonb_build_object('portfolio_projection',platform.portfolio_projection(r)) ELSE '{}'::jsonb END;\n          END IF;\n          RETURN jsonb_build_object('allowed',true);\n        ELSIF p_op='RESERVE' THEN\n          b:=p->'budget'; n:=r.calls_used+1;\n          IF NOT platform.material_object(p,ARRAY['run_id','budget']) OR NOT platform.material_object(b,ARRAY['calls_used','reads_reserved','tokens_reserved','cost_reserved','currency'])\n            OR jsonb_typeof(b->'calls_used')<>'number' OR jsonb_typeof(b->'reads_reserved')<>'number' OR jsonb_typeof(b->'tokens_reserved')<>'number' THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          tokens:=(b->>'tokens_reserved')::int; cost:=(b->>'cost_reserved')::numeric;\n          IF n>2 OR n>(lim->>'model_calls')::int OR (b->>'calls_used')::int<>n OR (b->>'reads_reserved')::int<>r.reads_used\n            OR b->>'currency' IS DISTINCT FROM lim->>'currency' OR tokens<=r.tokens_reserved OR tokens>(lim->>'total_tokens')::int\n            OR tokens-r.tokens_reserved>(lim->>'input_tokens')::int+(lim->>'output_tokens')::int\n            OR cost<>r.cost_reserved+(lim->>'call_cost_reservation')::numeric OR cost>(lim->>'cost_budget')::numeric\n            OR (n=2 AND (r.reads_used<>1 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'TOOLS')) THEN\n            RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          IF r.config->'route'->>'execution'='PROVIDER' AND EXISTS(\n            SELECT 1 FROM platform.ai_provider_sessions s WHERE s.id=(SELECT provider_session_id FROM platform.ai_deliveries WHERE job_id=j.id) AND\n            (EXISTS(SELECT 1 FROM platform.ai_provider_calls pc JOIN platform.ai_runs ar ON (ar.workspace_id,ar.id)=(pc.workspace_id,pc.run_id)\n              JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(ar.workspace_id,ar.job_id)\n              WHERE d.provider_session_id=s.id AND (pc.completed_at IS NULL OR pc.completion->>'kind'='UNKNOWN'\n                OR pc.completion->'cost'->>'status'='UNKNOWN'\n                OR (pc.completion->'cost'->>'amount')::numeric>(ar.config->'limits'->>'call_cost_reservation')::numeric))\n            OR (SELECT count(*) FROM platform.ai_provider_calls pc JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(pc.workspace_id,(SELECT job_id FROM platform.ai_runs WHERE workspace_id=pc.workspace_id AND id=pc.run_id)) WHERE d.provider_session_id=s.id)>=s.max_calls\n            OR (SELECT coalesce(sum(greatest((ar.config->'limits'->>'call_cost_reservation')::numeric,coalesce((pc.completion->'cost'->>'amount')::numeric,0))),0)\n              FROM platform.ai_provider_calls pc JOIN platform.ai_runs ar ON (ar.workspace_id,ar.id)=(pc.workspace_id,pc.run_id)\n              JOIN platform.ai_deliveries d ON (d.workspace_id,d.job_id)=(ar.workspace_id,ar.job_id) WHERE d.provider_session_id=s.id)\n              +(lim->>'call_cost_reservation')::numeric>s.max_rub)) THEN\n            RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n          IF r.config->>'prompt_revision'='conversation_v5' THEN\n            auxiliary:=platform.portfolio_auxiliary_cost(r.workspace_id,r.business_id,r.client_id,r.conversation_id,r.media_pin,r.id);\n            SELECT auxiliary+coalesce(sum(greatest((lim->>'call_cost_reservation')::numeric,\n              coalesce((pc.completion->'cost'->>'amount')::numeric,(lim->>'call_cost_reservation')::numeric))),0)\n              +(lim->>'call_cost_reservation')::numeric INTO auxiliary\n              FROM platform.ai_provider_calls pc WHERE pc.workspace_id=r.workspace_id AND pc.run_id=r.id;\n            IF greatest(cost,auxiliary)>(lim->>'cost_budget')::numeric THEN RAISE EXCEPTION 'AI_BUDGET' USING ERRCODE='P2001'; END IF;\n            PERFORM platform.portfolio_session_lock(r.workspace_id,r.business_id,r.portfolio_session_id,(lim->>'call_cost_reservation')::numeric);\n            cost:=greatest(cost,auxiliary);\n          END IF;\n          INSERT INTO platform.ai_provider_calls(workspace_id,run_id,sequence,claim_hash,attempt_count,budget,portfolio_session_id)\n            VALUES(j.workspace_id,r.id,n,sha256(convert_to(p_claim::text,'UTF8')),j.attempt_count,b,r.portfolio_session_id);\n          UPDATE platform.ai_runs SET calls_used=n,tokens_reserved=tokens,cost_reserved=cost WHERE workspace_id=j.workspace_id AND id=r.id;\n          RETURN jsonb_build_object('sequence',n);\n        ELSIF p_op='COMMIT' THEN\n          IF NOT platform.material_object(p,ARRAY['run_id','result']) OR platform.ai_runtime_result_valid(p->'result') IS NOT TRUE THEN\n            RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001'; END IF;\n          IF r.calls_used=0 OR previous.completed_at IS NULL OR previous.completion->>'kind'<>'OUTPUT' THEN RAISE EXCEPTION 'AI_INCOMPLETE' USING ERRCODE='P2001'; END IF;\n          PERFORM platform.messaging_guard(p_job,p_claim);\n          UPDATE platform.ai_runs SET result=p->'result',selected_at=clock_timestamp(),winning_claim_hash=sha256(convert_to(p_claim::text,'UTF8'))\n            WHERE workspace_id=j.workspace_id AND id=r.id AND result IS NULL RETURNING * INTO r;\n          PERFORM platform.ai_delivery_select(j,r);\n          UPDATE platform.messaging_jobs SET status='SUCCEEDED',turn_outcome='OBSERVED',error_code=NULL,claim_token=NULL,lease_until=NULL,\n            worker_id=NULL,completed_at=clock_timestamp(),version=version+1 WHERE id=j.id;\n          RETURN platform.ai_runtime_receipt(r);\n        END IF;\n        RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001';\n      EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_datetime_format OR datetime_field_overflow THEN\n        RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2001';\n      END $$",
    "platform.ai_runtime_view(platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_view(r platform.ai_runs) RETURNS jsonb\n      LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      SELECT jsonb_build_object('run_id',r.id,'binding',r.binding,'snapshot',r.snapshot,'storage_fingerprint',r.storage_fingerprint,\n        'config',r.config,'deadline',r.deadline,'reads_used',r.reads_used,'budget',jsonb_build_object(\n          'calls_used',r.calls_used,'reads_reserved',r.reads_used,'tokens_reserved',r.tokens_reserved,\n          'cost_reserved',r.cost_reserved::text,'currency',r.config->'limits'->>'currency'))\n        ||CASE WHEN r.knowledge_pin IS NULL THEN '{}'::jsonb ELSE\n          jsonb_build_object('knowledge_pin',r.knowledge_pin,'active_projection',r.active_projection) END\n        ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs) ELSE '{}'::jsonb END||platform.portfolio_runtime_data(r) $$",
    "platform.ai_runtime_receipt(platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_runtime_receipt(r platform.ai_runs) RETURNS jsonb\n      LANGUAGE sql STABLE SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      SELECT jsonb_build_object('run_id',r.id,'job_id',r.job_id,'turn_id',r.turn_id,'turn_revision',r.turn_revision,\n        'selected_at',r.selected_at,'result',r.result,'send_permit',false)\n        ||CASE WHEN r.knowledge_pin IS NULL THEN '{}'::jsonb ELSE jsonb_build_object('knowledge_pin',r.knowledge_pin) END\n        ||CASE WHEN r.search_pin IS NOT NULL THEN jsonb_build_object('search_pin',r.search_pin,'search_refs',r.search_refs) ELSE '{}'::jsonb END||CASE WHEN r.config->>'prompt_revision'='conversation_v5' THEN jsonb_build_object('portfolio_pin',r.portfolio_pin,'media_pin',r.media_pin,'portfolio_refs',r.portfolio_refs) ELSE '{}'::jsonb END $$",
    "platform.knowledge_runtime_current(platform.ai_runs)": "CREATE FUNCTION platform.knowledge_runtime_current(r platform.ai_runs) RETURNS boolean\nLANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\nDECLARE j platform.messaging_jobs%ROWTYPE; state platform.business_configuration_state%ROWTYPE;\nBEGIN\n  IF r.config->>'prompt_revision' NOT IN ('conversation_v4','conversation_v5') THEN RETURN true; END IF;\n  j:=platform.messaging_guard(nullif(current_setting('asm.job_id',true),'')::uuid,nullif(current_setting('asm.claim_token',true),'')::uuid);\n  IF j.workspace_id<>r.workspace_id OR j.connection_id<>r.connection_id THEN RETURN false; END IF;\n  PERFORM pg_advisory_xact_lock(hashtextextended(r.workspace_id::text||':'||r.business_id::text||'|CONFIGURATION_V1',2018));\n  SELECT * INTO state FROM platform.business_configuration_state WHERE workspace_id=r.workspace_id AND business_id=r.business_id;\n  RETURN r.search_pin IS NOT NULL AND r.search_pin=platform.knowledge_availability(r.workspace_id,r.business_id,state.active_release_id,coalesce(state.activation_version,0)) AND platform.portfolio_runtime_current(r);\nEND $$",
    "platform.ai_delivery_select(platform.messaging_jobs,platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_delivery_select(j platform.messaging_jobs,r platform.ai_runs) RETURNS void\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE d platform.ai_deliveries%ROWTYPE; c app.conversations%ROWTYPE; conn app.channel_connections%ROWTYPE;\n        msg uuid; box uuid; send uuid; intent_context bigint; e jsonb;\n      BEGIN\n        SELECT * INTO d FROM platform.ai_deliveries WHERE workspace_id=j.workspace_id AND job_id=j.id FOR UPDATE;\n        IF NOT FOUND THEN RETURN; END IF; -- historical DB-only run: no retroactive intent\n        IF d.selected_kind IS NOT NULL OR r.result IS NULL OR r.winning_claim_hash IS DISTINCT FROM sha256(convert_to(j.claim_token::text,'UTF8')) THEN\n          RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2001'; END IF;\n        PERFORM platform.ai_runtime_current(j,r.snapshot);\n        IF platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        SELECT * INTO STRICT c FROM app.conversations WHERE workspace_id=j.workspace_id AND id=r.conversation_id;\n        SELECT * INTO STRICT conn FROM app.channel_connections WHERE workspace_id=j.workspace_id AND id=j.connection_id;\n        IF r.result->>'kind'='reply' THEN\n          IF conn.provider='TELEGRAM' AND platform.telegram_can_send(j.workspace_id,j.connection_id,c.id,false) IS NOT TRUE THEN\n            RAISE EXCEPTION 'NOT_ALLOWED' USING ERRCODE='P2001'; END IF;\n          INSERT INTO app.messages(workspace_id,conversation_id,connection_id,provider_chat_id,direction,content_type,text,occurred_at)\n            VALUES(j.workspace_id,c.id,j.connection_id,c.provider_chat_id,'OUTBOUND','TEXT',r.result->>'text',clock_timestamp()) RETURNING id INTO msg;\n          SELECT version INTO STRICT intent_context FROM app.conversations WHERE workspace_id=j.workspace_id AND id=c.id;\n          IF intent_context::numeric<>(r.binding->>'context_version')::numeric+1 THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n          INSERT INTO app.outbox_events(workspace_id,connection_id,message_id,kind)\n            VALUES(j.workspace_id,j.connection_id,msg,'SEND_AI_TEXT') RETURNING id INTO box;\n          INSERT INTO platform.messaging_jobs(workspace_id,connection_id,kind,outbox_id,correlation_id)\n            VALUES(j.workspace_id,j.connection_id,'SEND_AI_TEXT',box,j.correlation_id) RETURNING id INTO send;\n        ELSIF r.result->>'kind'='handoff' THEN\n          e:=platform.escalation_request_for_turn(j.id,j.claim_token);\n          IF e->>'code' IS DISTINCT FROM 'ESCALATED' THEN RAISE EXCEPTION 'AI_STALE' USING ERRCODE='P2001'; END IF;\n        END IF;\n        IF j.lease_until<=clock_timestamp() THEN RAISE EXCEPTION 'STALE_CLAIM' USING ERRCODE='P2001'; END IF;\n        UPDATE platform.ai_deliveries SET knowledge_pin=r.knowledge_pin,search_pin=r.search_pin,portfolio_pin=r.portfolio_pin,media_pin=r.media_pin,run_id=r.id,selected_kind=r.result->>'kind',message_id=msg,outbox_id=box,send_job_id=send,\n          intent_context_version=intent_context,escalation_id=(e->>'escalation_id')::uuid WHERE workspace_id=j.workspace_id AND job_id=j.id;\n      END $$",
    "platform.ai_delivery_current(platform.messaging_jobs,platform.ai_deliveries,platform.ai_runs)": "CREATE OR REPLACE FUNCTION platform.ai_delivery_current(j platform.messaging_jobs,d platform.ai_deliveries,r platform.ai_runs) RETURNS boolean\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE t app.conversation_turns%ROWTYPE; c app.conversations%ROWTYPE; resume platform.conversation_control_receipts%ROWTYPE;\n        allowed boolean;\n      BEGIN\n        SELECT * INTO STRICT resume FROM platform.conversation_control_receipts WHERE workspace_id=j.workspace_id AND id=r.resume_receipt_id;\n        IF platform.messaging_lock_owner(j.workspace_id,resume.actor_user_account_id) IS NOT TRUE THEN RETURN false; END IF;\n        PERFORM 1 FROM app.businesses WHERE (workspace_id,id)=(j.workspace_id,r.business_id) AND status='ACTIVE' FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(j.workspace_id::text||':'||r.business_id::text||'|CONFIGURATION_V1',2018));\n        IF r.knowledge_pin IS NULL OR d.knowledge_pin IS DISTINCT FROM r.knowledge_pin OR platform.ai_knowledge_current(r) IS NOT TRUE OR platform.knowledge_runtime_current(r) IS NOT TRUE OR d.search_pin IS DISTINCT FROM r.search_pin OR d.portfolio_pin IS DISTINCT FROM r.portfolio_pin OR d.media_pin IS DISTINCT FROM r.media_pin THEN RETURN false; END IF;\n        PERFORM 1 FROM app.channel_connections WHERE (workspace_id,id,business_id)=(j.workspace_id,j.connection_id,r.business_id)\n          AND status='ACTIVE' AND (provider='CONTROLLED' OR (current_database()='asm_test' AND provider='TELEGRAM')) FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM platform.messaging_lock_billing_workspace(j.workspace_id);\n        SELECT * INTO STRICT c FROM app.conversations WHERE workspace_id=j.workspace_id AND id=r.conversation_id FOR NO KEY UPDATE;\n        SELECT * INTO STRICT t FROM app.conversation_turns WHERE workspace_id=j.workspace_id AND id=r.turn_id FOR NO KEY UPDATE;\n        PERFORM 1 FROM app.clients WHERE (workspace_id,id)=(j.workspace_id,r.client_id) FOR SHARE;\n        IF NOT FOUND THEN RETURN false; END IF;\n        PERFORM platform.messaging_guard(j.id,j.claim_token);\n        IF (c.client_id,c.business_id,c.connection_id,c.version,t.revision,t.state,t.control_generation,t.activation_fence_seq) IS DISTINCT FROM\n          (r.client_id,r.business_id,r.connection_id,d.intent_context_version,r.turn_revision,'READY',r.control_generation,(r.binding->>'activation_fence_seq')::bigint)\n          OR (resume.operation,resume.conversation_id,resume.client_id,resume.accepted_generation,resume.activation_fence_seq) IS DISTINCT FROM\n            ('RESUME',c.id,c.client_id,t.control_generation,t.activation_fence_seq)\n          OR platform.conversation_turn_activation_matches(j.workspace_id,t.id) IS NOT TRUE\n          OR platform.material_turn_usable(j.workspace_id,t.id) IS NOT TRUE\n          OR platform.human_context_admission(j.workspace_id,c.id,r.snapshot-'code'-'job_id') IS DISTINCT FROM 'CURRENT'\n          OR EXISTS(SELECT 1 FROM app.escalations WHERE workspace_id=j.workspace_id AND conversation_id=c.id AND status='PENDING') THEN RETURN false; END IF;\n        BEGIN allowed:=platform.messaging_manual_send_allowed(j.workspace_id);\n        EXCEPTION WHEN SQLSTATE 'P2301' THEN RETURN false; END;\n        IF d.provider_session_id IS NOT NULL AND allowed IS TRUE THEN\n          BEGIN PERFORM platform.ai_provider_guard(d.provider_session_id,j,r.config);\n          EXCEPTION WHEN SQLSTATE 'P2001' THEN RETURN false; END;\n        END IF;\n        RETURN allowed IS TRUE;\n      END $$",
    "platform.ai_delivery_immutable()": "CREATE OR REPLACE FUNCTION platform.ai_delivery_immutable() RETURNS trigger\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      BEGIN\n        IF OLD.selected_kind IS NOT NULL OR\n          (to_jsonb(OLD)-ARRAY['portfolio_pin','media_pin','search_pin','knowledge_pin','run_id','selected_kind','message_id','outbox_id','send_job_id','escalation_id','intent_context_version']) IS DISTINCT FROM\n          (to_jsonb(NEW)-ARRAY['portfolio_pin','media_pin','search_pin','knowledge_pin','run_id','selected_kind','message_id','outbox_id','send_job_id','escalation_id','intent_context_version']) OR\n          NOT EXISTS(SELECT 1 FROM platform.ai_runs r WHERE r.workspace_id=NEW.workspace_id AND r.id=NEW.run_id AND r.job_id=NEW.job_id AND r.result->>'kind'=NEW.selected_kind AND r.knowledge_pin IS NOT NULL AND r.knowledge_pin=NEW.knowledge_pin AND r.search_pin IS NOT DISTINCT FROM NEW.search_pin AND r.portfolio_pin IS NOT DISTINCT FROM NEW.portfolio_pin AND r.media_pin IS NOT DISTINCT FROM NEW.media_pin) THEN\n          RAISE EXCEPTION 'immutable AI delivery' USING ERRCODE='23514'; END IF;\n        RETURN NEW;\n      END $$",
    "platform.human_context_policy_command(uuid,uuid,text,text,text,bigint,jsonb,jsonb)": "CREATE OR REPLACE FUNCTION platform.human_context_policy_command(ws uuid,p_connection uuid,p_operation text,p_key text,\n        p_expected_policy text,p_expected_epoch bigint,p_binding jsonb,p_profile jsonb) RETURNS jsonb\n      LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,pg_temp AS $$\n      DECLARE c app.channel_connections%ROWTYPE; s platform.telegram_connection_state%ROWTYPE;\n        r platform.human_context_policy_receipts%ROWTYPE; prior platform.human_context_policy_receipts%ROWTYPE;\n        profile jsonb; fingerprint bytea; binding jsonb; allowed boolean; moment timestamptz; corr uuid;\n      BEGIN\n        IF session_user<>'asm_migrator' OR current_database() NOT IN ('asm_local','asm_test') THEN RAISE EXCEPTION 'ACCESS_DENIED' USING ERRCODE='P2601'; END IF;\n        PERFORM platform.turn_require_isolation();\n        IF ws IS NULL OR p_connection IS NULL OR p_operation IS NULL OR p_operation NOT IN ('ENABLE','PAUSE') OR p_key IS NULL OR p_key !~ '^[A-Za-z0-9._:-]{1,128}$'\n          OR p_expected_policy IS NULL OR p_expected_policy NOT IN ('OFF_UNUSED','ON','PAUSED') OR p_expected_epoch IS NULL OR p_expected_epoch<0\n          OR platform.material_object(p_binding,ARRAY['business_id','provider','bot_identity','external_connection_id','owner_user_id']) IS NOT TRUE\n          OR platform.material_object(p_profile,ARRAY['source_tree','schema_revision','profile_sha256','drain_confirmed']) IS NOT TRUE THEN\n          RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2601'; END IF;\n        IF NOT platform.human_context_uuid(p_binding->'business_id') OR jsonb_typeof(p_binding->'provider')<>'string' OR p_binding->>'provider' NOT IN ('CONTROLLED','TELEGRAM')\n          OR jsonb_typeof(p_binding->'bot_identity')<>'string' OR platform.messaging_valid_id(p_binding->>'bot_identity',128,512) IS NOT TRUE\n          OR jsonb_typeof(p_binding->'external_connection_id')<>'string' OR platform.messaging_valid_id(p_binding->>'external_connection_id',256,1024) IS NOT TRUE\n          OR NOT ((p_binding->>'provider'='CONTROLLED' AND p_binding->'owner_user_id'='null'::jsonb) OR\n            (p_binding->>'provider'='TELEGRAM' AND jsonb_typeof(p_binding->'owner_user_id')='string' AND platform.telegram_numeric_id(p_binding->>'owner_user_id') IS TRUE\n              AND platform.telegram_numeric_id(p_binding->>'bot_identity') IS TRUE))\n          OR jsonb_typeof(p_profile->'source_tree')<>'string' OR p_profile->>'source_tree' !~ '^[0-9a-f]{40}$'\n          OR jsonb_typeof(p_profile->'schema_revision')<>'string' OR p_profile->>'schema_revision'<>'0021'\n          OR jsonb_typeof(p_profile->'profile_sha256')<>'string' OR p_profile->>'profile_sha256' !~ '^[0-9a-f]{64}$'\n          OR p_profile->'drain_confirmed' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'INVALID_INPUT' USING ERRCODE='P2601'; END IF;\n        SELECT platform.portfolio_schema_profile() INTO profile;\n        IF profile->'valid' IS DISTINCT FROM 'true'::jsonb OR p_profile->>'profile_sha256' IS DISTINCT FROM profile->>'profile_sha256' THEN\n          RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n        PERFORM 1 FROM platform.workspaces WHERE id=ws FOR SHARE;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        PERFORM pg_advisory_xact_lock(hashtextextended(ws::text||':HUMAN_CONTEXT_POLICY_V1:'||p_key,2013));\n        SELECT * INTO c FROM app.channel_connections WHERE workspace_id=ws AND id=p_connection;\n        IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        PERFORM 1 FROM app.businesses WHERE workspace_id=ws AND id=c.business_id FOR SHARE;\n        SELECT * INTO STRICT c FROM app.channel_connections WHERE workspace_id=ws AND id=p_connection FOR UPDATE;\n        SELECT * INTO s FROM platform.telegram_connection_state WHERE workspace_id=ws AND connection_id=c.id FOR SHARE;\n        binding:=jsonb_build_object('business_id',c.business_id,'provider',c.provider,'bot_identity',c.bot_identity,\n          'external_connection_id',c.external_connection_id,'owner_user_id',CASE WHEN c.provider='TELEGRAM' THEN s.owner_user_id END);\n        IF binding IS DISTINCT FROM p_binding OR NOT EXISTS(SELECT 1 FROM platform.channel_routes WHERE workspace_id=ws AND connection_id=c.id\n          AND provider=c.provider AND bot_identity=c.bot_identity AND route_key=c.external_connection_id) OR\n          (c.provider='TELEGRAM' AND (s.bot_identity,s.external_connection_id,s.owner_user_id) IS DISTINCT FROM\n            (c.bot_identity,c.external_connection_id,p_binding->>'owner_user_id')) THEN RAISE EXCEPTION 'NOT_FOUND' USING ERRCODE='P2601'; END IF;\n        SELECT platform.portfolio_schema_profile() INTO profile;\n        IF session_user<>'asm_migrator' OR profile->'valid' IS DISTINCT FROM 'true'::jsonb OR p_profile->>'profile_sha256' IS DISTINCT FROM profile->>'profile_sha256' THEN\n          RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n        fingerprint:=platform.human_context_hash(E'asm:m3:human_context_policy:v1\\n',ARRAY[ws::text,session_user::text,c.id::text,p_operation,p_expected_policy,p_expected_epoch::text,\n          p_binding->>'business_id',p_binding->>'provider',p_binding->>'bot_identity',p_binding->>'external_connection_id',p_binding->>'owner_user_id',\n          p_profile->>'source_tree',p_profile->>'schema_revision',p_profile->>'profile_sha256','true']);\n        SELECT * INTO prior FROM platform.human_context_policy_receipts WHERE workspace_id=ws AND namespace='HUMAN_CONTEXT_POLICY_V1' AND idempotency_key=p_key;\n        IF FOUND THEN\n          IF prior.request_fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_CONFLICT' USING ERRCODE='P2601'; END IF;\n          RETURN jsonb_build_object('outcome','REPLAY','result',prior.result);\n        END IF;\n        IF (c.human_context_policy,c.human_context_policy_epoch) IS DISTINCT FROM (p_expected_policy,p_expected_epoch) THEN RAISE EXCEPTION 'STALE_STATE' USING ERRCODE='P2601'; END IF;\n        IF p_operation='PAUSE' AND c.human_context_policy='OFF_UNUSED' THEN RAISE EXCEPTION 'CONTEXT_POLICY_INACTIVE' USING ERRCODE='P2601'; END IF;\n        IF p_operation='ENABLE' THEN\n          IF NOT EXISTS(SELECT 1 FROM platform.workspaces WHERE id=ws AND status='ACTIVE')\n            OR NOT EXISTS(SELECT 1 FROM app.businesses WHERE workspace_id=ws AND id=c.business_id AND status='ACTIVE') OR c.status<>'ACTIVE'\n            OR (c.provider='TELEGRAM' AND s.material_enabled IS NOT TRUE) THEN RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n          BEGIN allowed:=platform.messaging_manual_send_allowed(ws);\n            EXCEPTION WHEN SQLSTATE 'P2301' THEN RAISE EXCEPTION 'UNAVAILABLE' USING ERRCODE='P2601'; END;\n          IF allowed IS NOT TRUE THEN RAISE EXCEPTION 'POLICY_PREREQUISITE_FAILED' USING ERRCODE='P2601'; END IF;\n          IF c.human_context_policy='PAUSED' AND c.human_context_policy_epoch=9223372036854775807 THEN\n            RAISE EXCEPTION 'POLICY_VERSION_EXHAUSTED' USING ERRCODE='P2601'; END IF;\n        END IF;\n        r.workspace_id:=ws; r.id:=uuidv7(); r.connection_id:=c.id; r.business_id:=c.business_id; r.provider:=c.provider;\n        r.bot_identity:=c.bot_identity; r.external_connection_id:=c.external_connection_id; r.owner_user_id:=p_binding->>'owner_user_id';\n        r.actor_db_role:=session_user; r.namespace:='HUMAN_CONTEXT_POLICY_V1'; r.idempotency_key:=p_key; r.request_fingerprint:=fingerprint;\n        r.operation:=p_operation; r.expected_policy:=p_expected_policy; r.expected_policy_epoch:=p_expected_epoch;\n        r.accepted_policy:=CASE WHEN p_operation='ENABLE' THEN 'ON' ELSE 'PAUSED' END;\n        r.accepted_policy_epoch:=p_expected_epoch+CASE WHEN p_operation='ENABLE' AND p_expected_policy<>'ON' THEN 1 ELSE 0 END;\n        r.change:=CASE WHEN r.accepted_policy=p_expected_policy THEN 'UNCHANGED' WHEN p_operation='ENABLE' THEN 'ENABLED' ELSE 'PAUSED' END;\n        r.source_profile:=p_profile; r.event_type:='HUMAN_CONTEXT_POLICY_COMMANDED'; r.accepted_at:=clock_timestamp(); corr:=uuidv7();\n        INSERT INTO app.audit_events(workspace_id,actor_kind,actor_user_account_id,correlation_id,event_type,object_type,object_id,object_version,payload)\n          VALUES(ws,'LOCAL_PROVISIONER',NULL,corr,r.event_type,'CHANNEL_CONNECTION',c.id,r.accepted_policy_epoch,\n            jsonb_build_object('receipt_id',r.id,'operation',r.operation,'change',r.change,'previous_policy',r.expected_policy,'accepted_policy',r.accepted_policy,\n              'previous_policy_epoch',r.expected_policy_epoch::text,'accepted_policy_epoch',r.accepted_policy_epoch::text)) RETURNING audit_event_id INTO r.audit_event_id;\n        r.result:=platform.human_context_policy_result(r);\n        INSERT INTO platform.human_context_policy_receipts SELECT r.*;\n        IF r.change<>'UNCHANGED' THEN UPDATE app.channel_connections SET human_context_policy=r.accepted_policy,\n          human_context_policy_epoch=r.accepted_policy_epoch WHERE workspace_id=ws AND id=c.id; END IF;\n        RETURN jsonb_build_object('outcome','ACCEPTED','result',r.result);\n      END $$",
}

